quests[11536] = { id = 11536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stop Now....", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I asked for?", completion = "Excellent! This will help me keep our soldiers in weapons and armor.\n\nYour help is truly making a difference!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Must Go On", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you succeeded, {name}?", completion = "Your dedication is exemplary, {name}.  We will show the forces of the Burning Legion what we're capable of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for the Sun's Reach Armory", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you done what I asked of you, {name}?", completion = "Your dedication is exemplary, {name}.  We will take the armory from the forces of the Legion in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Harbor", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", completion = "Excellent work, {class}.  Kael's armies will falter and once we take the harbor we shall deliver the killing blow!", sourceObjectiveStatus = "unverified-source-field" }
quests[11540] = { id = 11540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Dawnblade", description = "We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.\n\nI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", progress = "Have you slain the Dawnblade scum, {name}?", completion = "What thoughts go through Prince Kael'thas Sunstrider's head when he hears of his armies' defeats?\n\nDoes he feel despair?  Helplessness?  Fear?\n\nI sure hope so.", sourceObjectiveStatus = "unverified-source-field" }
quests[11541] = { id = 11541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt the Greengill Coast", description = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.\n\n{class}, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.", sourceObjective = "Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so.", progress = "My scouts tell me that there hasn't yet been enough disruption of the naga today.", completion = "That's enough for today. Slow and steady is the key here. Too much disruption and they'd turn their attention directly upon us; something that we don't want.\n\nCome back again tomorrow and we'll work on it some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11542] = { id = 11542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercept the Reinforcements", description = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", sourceObjective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", progress = "Have you accomplished your task, {name}?", completion = "Well done, {name}.  It should be a long time before the harbor receives any reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[11543] = { id = 11543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Enemy at Bay", description = "We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", sourceObjective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", progress = "Have you accomplished your task, {name}?", completion = "Well done, {name}.  It should be a long time before the harbor receives any reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[11544] = { id = 11544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ata'mal Armaments", description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.", sourceObjective = "Smith Hauthaa needs you to produce 5 Cleansed Ata'mal Metal. Do so by breaking down Ata'mal Armaments on her anvil at the Sun's Reach Armory on the Isle of Quel'Danas.", progress = "I need all of the cleansed Ata'mal metal that I can get my hands on, {class}.", completion = "Thank you, my friend. Now I will be able to fashion more of the special alloy that is going into the creation of our forces' weapons and armor.\n\nAnd, I have some leftover extract from the process, which you'll likely find handy for use on your weapons. Please, take your pick of whichever will serve your purposes.\n\nReturn to me again on the morrow. No doubt I will need more armaments.", sourceObjectiveStatus = "unverified-source-field" }
quests[11545] = { id = 11545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Charitable Donation", description = "We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.\n\nIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.", sourceObjective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, {name}.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11546] = { id = 11546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open for Business", description = "Welcome, {name}.\n\nThere are a number of ways I can assist you in your efforts here.\n\nFor example, I've recently discovered a recipe for a unique elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you what I mean.", sourceObjective = "Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas.", progress = "Have you gathered those berries yet?", completion = "Excellent, {name}.\n\nI hope this will aid you in your efforts here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11547] = { id = 11547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Your Ley Lines", description = "Freeloaders!\n\nYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.\n\nPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.\n\nTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.\n\nPerhaps then you'll appreciate your precious translocations....", sourceObjective = "Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast.", progress = "Have you attuned the crystal yet, {class}?", completion = "Yes, yes. Let's have a look now, shall we?\n\nThings seem to be in order. Very well. Here is your translocator.\n\nIf any of your readings are faulty, there's no telling where you'll end up, and mind you, you'll only have yourself to blame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11548] = { id = 11548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Continued Support", description = "We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.\n\nI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.", sourceObjective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, {name}.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11549] = { id = 11549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Magnanimous Benefactor", description = "You've done so much for us, {name}.  We greatly appreciate your assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.\n\nIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?", sourceObjective = "Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts. You will be known as {name} of the Shattered Sun if you complete this quest.", progress = "Are you ready to make the contribution?", completion = "You truly are a generous person and a worthy ally.  From now on you shall be known as {name} of the Shattered Sun and all who fought here will know of your deeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[11550] = { id = 11550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter, the Deceiver...", description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.", sourceObjective = "Report to Archmage Ne'thul on the Isle of Quel'Danas, north of Quel'Thalas.\n\nFlight masters in Ironforge and Silvermoon City will get you to your destination.", completion = "Kil'jaeden bears down upon this world with the full force of the Burning Legion. Should the summoning complete, our world will once more be flung into the throes of chaos. Your assistance on the Isle of Quel'Danas is critical to our success against the Burning Legion.\n\nOur mages are working on bringing down the barriers blocking access to the Sunwell. Do your part in battling the forces of the Legion by helping the Shattered Sun Offensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11551] = { id = 11551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamath, the First Gate" }
quests[11554] = { id = 11554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend in the Frontlines", sourceObjective = "Your aid in the offensive has not gone unnoticed, {name}.  The combined forces of the Aldor and Scryers offer you their thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11555] = { id = 11555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored by Your Allies", sourceObjective = "You continue to prove yourself in this most important battle, {name}.  Please accept this as a token of our continued gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11556] = { id = 11556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered in the Field of Battle", sourceObjective = "We couldn't have gotten where we are without you, {name}.  The combined might of the Aldor and Scryers is not enough to crush the Legion and Kael.  We are thankful to have allies of your caliber among us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11557] = { id = 11557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted Among All Combatants", sourceObjective = "You are one of our very best, {name}.  Your name will be known throughout our ranks for a long time to come.\n\nPlease accept this small gift on the behalf of our forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[11558] = { id = 11558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", sourceObjective = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this.", sourceObjectiveStatus = "unverified-source-field" }
quests[11559] = { id = 11559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfin Commerce", description = "Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them.\n\nThe murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him as a gift.\n\nThe clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.", sourceObjective = "Collect 5 Winterfin Clams and deliver them to Ahlurglgr at Winterfin Retreat.", progress = "What's this? Who are you?\n\nYou're one of those {race} things! How can you speak our tongue?", completion = "These are for me? Is this some sort of {race} trick? No?\n\nWell then, thank you! Come back any time that you have more clams, and we'll do business!", sourceObjectiveStatus = "unverified-source-field" }
quests[11560] = { id = 11560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Noes, the Tadpoles!", description = "Oh good, you're back!\n\nWhen the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away.\n\nSomething happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control.\n\n{class}, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns.\n\nThe future of the Winterfin tribe depends upon you!", sourceObjective = "King Mrgl-Mrgl has asked you to rescue 20 Winterfin Tadpoles. Return to him at Winterfin Retreat once you have done so.", completion = "Now no matter what happens, the Winterfin murlocs have a secure future.\n\nYou are to be commended, and rewarded, for your selflessness, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11561] = { id = 11561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Them!", description = "Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count.\n\nProve yourself, {race}! Swim across the rift and slay them!\n\nDespite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!", sourceObjective = "Brglmurgl at Winterfin Retreat has asked you to kill 15 Winterfin murlocs. Any combination of warriors, oracles, and shorestrikers will do.", progress = "If you have killed so many of the Winterfin betrayers, why is it that when I look out across the water, I still see too many of them?", completion = "I am pleased. I can smell the coppery tang of their blood on your hands.\n\nThis is a good start for you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11562] = { id = 11562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Being Blackmailed By My Cleaner", description = "I have something embarrassing to admit: I'm being blackmailed!\n\nMrmrglmr agreed to clean some of my things, and got hold of my spare murloc costume. He's threatening to reveal my true nature to the other murlocs.\n\nI need not explain to you what a disaster that would be! Besides, I have a plan that's going to require that we get that costume back.\n\nPlease, {name}, go to Mrmrglmr at the other end of the Retreat to the north and do whatever he asks of you.", sourceObjective = "King Mrgl-Mrgl has asked you to speak with Mrmrglmr at the northwest end of Winterfin Retreat.", completion = "Aw, so you must be the so-called King Mrgl-Mrgl's lackey. I suppose that night elf has sent you to appease me?\n\nGood, I have just the thing that needs doing for someone as powerful as you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11563] = { id = 11563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grmmurggll Mrllggrl Glrggl!!!", description = "If your pathetic little eyes were any good, you'd see that we're being slaughtered by the orcas to the north in the bay!\n\nAssuming your precious night elf king wants his spare costume back, I think you'll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves!\n\nBe quick about it, {race}, Winterfin murlocs are losing their lives even as we waste time talking!", sourceObjective = "Mrmrglmr wants you to return to him at Winterfin Retreat with Glrggl's Head.", progress = "If you don't have Glrggl's head, don't waste my time!", completion = "Not bad. This will make a nice feast!\n\nWith the king of the orcas dead the attacks upon us should diminish while the whales fight amongst themselves for dominance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11564] = { id = 11564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Succulent Orca Stew", description = "Word is, strange {race}, that you might be going after the king of the orcas, Glrggl.\n\nThat's all fine and good, but if you want to taste the stew that makes life worth living, then you'll bring me back the succulent blubber of the orcas that swim in Glimmer Bay.\n\nHurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.", sourceObjective = "Cleaver Bmurglbrm has tasked you with acquiring 7 Succulent Orca Blubber. Return with them to him at Winterfin Retreat.", progress = "Do you have all of the orca blubber that I require?", completion = "Ah yes, these will do nicely.\n\nJust plop them down anywhere. You can have some of my leftover stew from last night.", sourceObjectiveStatus = "unverified-source-field" }
quests[11565] = { id = 11565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spare Suit", description = "Very well, your king's secret is safe with me as long as he continues to help us against our enemies.\n\nHere, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise.\n\nMaybe he has something in mind for you?", sourceObjective = "Return King Mrgl-Mrgl's Spare Suit to him at Winterfin Retreat.", progress = "Do you have my spare suit, {name}?", completion = "<Upon seeing the spare murloc suit, the king rubs his costumed appendages together.>\n\nNicely done. Now, back to the pressing matter at hand. I've got something of great importance for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11566] = { id = 11566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrender... Not!", description = "The time has come to put an end to this unnatural situation, {name}. For the Winterfin murlocs to have a chance at a future, Claximus must die!\n\nI want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won't attack you.\n\nYou'll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.", sourceObjective = "King Mrgl-Mrgl at Winterfin Retreat has asked you to bring him a Claw of Claximus.", progress = "Have you done it, {class}? Is Claximus dead?", completion = "Regrettable, but necessary. I'll take the claw, {name}.\n\nThank you for all of the help you've given us. With Claximus defeated, maybe we'll be able to reunite the remaining murlocs and seal off those caverns.\n\nPlease, my friend, take this... it's the least I can do for all of the help you have rendered us!", sourceObjectiveStatus = "unverified-source-field" }
quests[11567] = { id = 11567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Armor of the Kvaldir", description = "I was on the vessel that was bringing in the armor. We'd just boarded the ship and were headin' back here when we were attacked by a Forsaken destroyer.\n\nThey boarded our ship, took all the booty for themselves, and then sunk her.\n\nThat was the last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get you on the bomber.\n\nIf you manage to find the stuff, don't you dare bring it back!", sourceObjective = "Recover the Ancient Armor of the Kvaldir and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "Have you found the armor?", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11568] = { id = 11568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Return to Resting", description = "<Orfus hands you a satchel.>\n\nWithin this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds.\n\nBe strong, {name}...", sourceObjective = "Use the Bundle of Vrykul Artifacts at the ransacked burial mounds of Shield Hill to return the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm's Fury and the Ancient Armor of the Kvaldir.\n\nReturn to Orfus of Kamagua at the Ancient Lift should you succeed.", progress = "Is it done? Are the spirits at rest?", completion = "Grim tidings, {name}. My people are in danger and must be warned. These sea faring aberrations will take no mercy upon the Kalu'ak.", sourceObjectiveStatus = "unverified-source-field" }
quests[11569] = { id = 11569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keymaster Urmgrgl", description = "I have to get out of these caverns! There's magic stuff seeping in from Coldarra, above, and affecting everyone's minds.\n\nI don't intend to be controlled like these others!\n\nKeymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here.\n\nHurry!", sourceObjective = "Glrglrglr inside the Winterfin Caverns has asked you to retrieve Urmgrgl's Key.", progress = "Do you have the key?\n\nNo, I don't care about any of these others. I just want to get out of here!", completion = "Quickly, hand it here!", sourceObjectiveStatus = "unverified-source-field" }
quests[11570] = { id = 11570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from the Winterfin Caverns", description = "The lock on my cage doesn't look too solid, but I'm not foolish enough to try to leave without assistance.\n\nWill you help me safely get out of these caverns? There's no time to waste, {race}.\n\nWhen you get back to the retreat, please let the king know that I'm okay. He's sure to give you a reward.", sourceObjective = "Escort Lurgglbr to safety and then report to King Mrgl-Mrgl at Winterfin Retreat with the good news.", completion = "This is wonderful news! And you say that Lurgglbr discovered that the emanations from the caverns are what caused this insanity?\n\nIt must be that the magic from Coldarra is growing stronger. The Nexus War... the battle between the blue dragonflight and all of the other dragons, is spilling over.\n\nSoon, we will all be embroiled in it!", sourceObjectiveStatus = "unverified-source-field" }
quests[11571] = { id = 11571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Communicate", description = "To help, you must learn how to speak the Winterfin dialect. We'll work with the forces of nature and magic to do that.\n\nTake this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury.\n\nOnce she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I'll imbue my knowledge of the Winterfin tongue into you.\n\nLuckily, a friend taught me a water breathing spell, which I will cast upon you.", sourceObjective = "King Mrgl-Mrgl has given you a conch to use upon Scalder's remains. Return The King's Filled Conch to him at Winterfin Retreat.", progress = "Have you managed to fill the conch with Scalder's steam?", completion = "Now I will be able to use Scalder's essence to impart my understanding of the Winterfin murloc tongue to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11572] = { id = 11572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Atuik", description = "Return to Elder Atuik at Kamagua. He and the rest of my people must be warned of this impending doom that approaches from the sea.\n\n<Orfus shivers.>\n\nUse the Ancient Lift to reach him. Please hurry!", sourceObjective = "Deliver the bad news to Elder Atuik at Kamagua.", completion = "The Kalu'ak thank you for all that you have done, {name}. We must now prepare for battle and warn our brothers and sisters across the sea of what is to come.\n\nI hope it is not too late...", sourceObjectiveStatus = "unverified-source-field" }
quests[11573] = { id = 11573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orfus of Kamagua", description = "Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your people. My partner and I were recently sent up to investigate strange happenings along one of our hunting trails. It was when we approached the graveyard known as Shield Hill that we were attacked by the undead. I was lucky to make it to this camp, but I am uncertain as to what became of Orfus.\n\nWe parted ways at the Ancient Lift, southeast of here along the cliff edge. Will you go see if he is ok?", sourceObjective = "Find Orfus of Kamagua at the Ancient Lift in Howling Fjord.", completion = "Lunk-tusk lives? At least there is some good news to be had on this day...", sourceObjectiveStatus = "unverified-source-field" }
quests[11574] = { id = 11574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Close For Comfort", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was surrounded!\n\nA magical box appeared above me, opened up and pulled me inside. Just as it began to close around me, my rescuers swooped in on the backs of red drakes. It was breathtaking!\n\nI never thanked them for saving me. Please, {class}, find them, and pass on my gratitude.", sourceObjective = "Endorah wants you to go to Amber Ledge north of Warsong Hold and thank those there for rescuing her.", completion = "You can tell your friend that her rescue was our pleasure, as well as our duty.\n\nHer encounter was but a small piece in what I believe to be a large puzzle.\n\nDalaran is sparing no effort in solving this mystery and to be honest, we could use a bit of assistance....", sourceObjectiveStatus = "unverified-source-field" }
quests[11575] = { id = 11575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nick of Time", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was surrounded!\n\nA huge magical cube appeared above me. It opened up and pulled me inside. I swear it's true!\n\nJust as it began to close around me, my rescuers swooped in on the backs of drakes - It was amazing! My captors scattered and I was able to escape.\n\nI never thanked them for saving me. Please, {class}, if you see them, pass on my gratitude.", sourceObjective = "Midge in Valiance Keep wants you to go to Amber Ledge to the north and thank those there for rescuing her.", completion = "You can tell your friend that her rescue was our pleasure, as well as our duty.\n\nHer encounter was but a small piece in what I believe to be a large puzzle.\n\nDalaran is sparing no effort in solving this mystery and to be honest, we could use a bit of assistance....", sourceObjectiveStatus = "unverified-source-field" }
quests[11576] = { id = 11576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Cleftcliff Anomaly", description = "Greetings, {race}. I am Garren of Dalaran.\n\nNot long ago, the rift was a peaceful place - geothermally speaking at least.\n\nRecently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power.\n\nMy mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest.\n\nTake this device with you and use it when you locate the new disruption.", sourceObjective = "Garren on Amber Ledge wants you to use the Arcanometer at the Cleftcliff Anomaly.", progress = "Have you taken the readings I requested, {class}?", completion = "Fascinating! This is the largest disruption yet.\n\nThough the worst is yet to come, I fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11578] = { id = 11578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Chow\" Quest (123)aa COPY", sourceObjective = "Kill Kobold Vermin, 2 of em.", sourceObjectiveStatus = "unverified-source-field" }
quests[11579] = { id = 11579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Chow\" Quest (123)aa COPY", sourceObjective = "Kill Kobold Vermin, 2 of em.", sourceObjectiveStatus = "unverified-source-field" }
quests[11580] = { id = 11580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Silverpine bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11581] = { id = 11581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Westfall bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11582] = { id = 11582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Sundered Chasm", description = "Did you feel that?! That was just an aftershock... you should've been here a few minutes ago!\n\nI'm afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water's surface.\n\nJust as before, I need you to take the arcanometer and capture the anomaly's data.\n\nI'll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I'll renew its effects.", sourceObjective = "Garren at Amber Ledge wants you to use the Arcanometer at the Sundered Chasm anomaly and return to him with the readings.", completion = "It was how big?\n\nThat's impossible! I need to report to Dalaran at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[11583] = { id = 11583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Westfall flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11584] = { id = 11584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Silverpine Forest flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11585] = { id = 11585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", sourceObjective = "Speak with Garrosh Hellscream in Warsong Hold.", completion = "A hero of the Horde, eh?\n\n<Garrosh sniffs at the air around you.>\n\nFear...\n\n<Garrosh spits.>\n\nYou won't last long.", sourceObjectiveStatus = "unverified-source-field" }
quests[11586] = { id = 11586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", sourceObjective = "Speak with Garrosh Hellscream in Warsong Hold.", completion = "Do not think that I have forgotten what you did for my people in Nagrand, {name}. Hellscream never forgets.\n\nFor that I am indebted to you and it is why I give you this chance now: run. Leave this place and never look back.\n\nReturn to your home and say a prayer for the dying.", sourceObjectiveStatus = "unverified-source-field" }
quests[11587] = { id = 11587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Break", description = "Greetings, {class}. I am Donathan, a loyal representative of Dalaran.\n\nForgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery.\n\nThe camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.", sourceObjective = "Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison.", progress = "I trust you are working diligently to rescue an imprisoned {class}....", completion = "You have done well, {name}.\n\nThe Kirin Tor graciously accept the assistance you have rendered. Know that any service you provide us will not go unrewarded.\n\nPlease, accept this humble offering as a token of Dalaran's appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[11590] = { id = 11590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abduction", description = "{name}, we have a situation.\n\nI've just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance.\n\nTime is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her.\n\nTake this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.", sourceObjective = "Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him.", progress = "Have you captured a Beryl sorcerer yet, {name}?", completion = "Excellent work, {name}.\n\nWe'll have him prepared for his interrogation at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[11591] = { id = 11591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Steeljaw's Caravan", description = "That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a shortcut through a taunka graveyard!\n\nWe just struck up relations with them!\n\nNow the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves as he was trampling them.\n\nHead south and see if you can salvage the situation, {class}. I sent Grunt Ragefist and a few others down there with him to help out.\n\nWhy don't you see if you can lend a hand.", sourceObjective = "Speak with Grunt Ragefist at Steeljaw's Caravan.", completion = "This isn't good, {class}.\n\nLongrunner Proudhoof says that these are the burial grounds of his honored ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[11592] = { id = 11592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Strike!", description = "One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, {race}, or you will find the taunka to be the end of you!\n\nBut, you look as if you want to help fix this situation. Good!\n\nSteeljaw's cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him!\n\nIf we live through this, tell your Overlord Bor'gorok at the outpost to the north.\n\nAre you with me?", sourceObjective = "Help Longrunner Proudhoof and his Warsong raiders to survive the assault upon Steeljaw's Caravan and finish off the spirit of Force-Commander Steeljaw.\n\nIf successful, report to Overlord Bor'gorok at Bor'gorok Outpost.", completion = "Blood and thunder! You've salvaged our newborn relations with the taunka.\n\nThank you for putting the situation to rights. Aka'Magosh, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11593] = { id = 11593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Honored Dead", description = "Our fallen deserve a hero's funeral, but we cannot bury them here on sacred taunka ground.\n\nI'll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch.\n\nHonor our dead, {class}!", sourceObjective = "Grunt Ragefist at Steeljaw's Caravan has asked you to use Ragefist's Torch to burn any combination of 10 Dead Carvan Guards and Workers.", completion = "Thank you, {class}. We are the Horde, we do not leave our dead behind!\n\nIt should never have been necessary in the first place. Steeljaw was a fool!", sourceObjectiveStatus = "unverified-source-field" }
quests[11594] = { id = 11594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Them to Rest", description = "Force-Commander Steeljaw's idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound?\n\nStill, what's done is done. Now it is up to us to deal with the consequences.\n\nOverlord Bor'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors.\n\nWhat do you say, {class}? Are you <man/strong> enough to handle such a simple task?", sourceObjective = "Put 20 taunka spirits, either Ghostly Sages or Risen Longrunners, to rest and then report back to Grunt Ragefist at Steeljaw's Caravan.", completion = "Well done, {class}! You must have a great deal of experience fighting the undead. And, if you didn't before, you have some now.\n\nYou'll need it if you're going to survive in Northrend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11595] = { id = 11595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Warsong Hold", description = "Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, {name}.\n\n<Saurfang nods.>\n\nDid you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike!\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", sourceObjective = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "<Overlord Razgor salutes.>\n\nYour reputation precedes you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11596] = { id = 11596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Warsong Hold", description = "Do not let Hellscream dissuade you from your duties as a soldier of the Horde, {race}. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom.\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", sourceObjective = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "Just in time... The Nerubians have seemingly doubled in number in just a week's time. We could use all the help we can get out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11597] = { id = 11597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Warsong Hold", description = "It seems that we always meet in the direst of circumstances, Scarab Lord. Were you not saving the world from certain destruction the last time we met?\n\n<Saurfang chuckles.>\n\nYour assistance is most welcome in Northrend, despite what the young chieftain might say.\n\nIf we had even a dozen more soldiers with your power, we would be sitting in Orgrimmar right now, hunched over a warm fire.\n\nReport to Overlord Razgor, right outside the main entry to Warsong Hold, to the south.", sourceObjective = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "<Overlord Razgor salutes.>\n\nA living legend battles among us! Your presence alone rouses the spirits of this army!", sourceObjectiveStatus = "unverified-source-field" }
quests[11598] = { id = 11598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Mightstone Quarry", description = "While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians.\n\n<Razgor points west.>\n\nBeyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas.\n\nWe can't let that happen - which is why you're going on the offensive and slaughtering the Nerubians in the quarry.\n\nBlood and thunder, soldier! Take 'em both with you.", sourceObjective = "Overlord Razgor at Warsong Hold wants you to kill 15 Nerub'ar Nerubians.", completion = "You've slowed them down, but more are sure to join the fight. Were you able to locate any of their egg sacs while in the quarry?", sourceObjectiveStatus = "unverified-source-field" }
quests[11599] = { id = 11599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thassarian, My Brother", description = "I recently received word from William Allerton, a family friend, that my brother enlisted here in Valiance Keep on the same day he did.  Thing is... my brother's been dead for years.\n\nI sold everything I owned to come looking for Thassarian, only to be stonewalled by the local bureaucracy.  I've even been threatened with arrest if I keep snooping around.\n\nI need someone in the good graces of the higher-ups... someone like you.  If you can help me, I heard that William's stationed at the Farshire mine.", sourceObjective = "Look for William Allerton inside the Farshire mine.", completion = "The corpse matches the description that Leryssa gave you of William Allerton.  Oddly enough, there are no bite or claw marks on him.", sourceObjectiveStatus = "unverified-source-field" }
quests[11600] = { id = 11600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Late William Allerton", description = "William's neck has been cut by a sharp object.\n\nFurther inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.", sourceObjective = "Bring the Enlistment Card to Leryssa at Valiance Keep in Borean Tundra.", progress = "You spoke to William, {name}?", completion = "Do you think William's death was a random killing by the Scourge?  Things sure seem fishy.\n\nSomething's up.  We must find Thassarian.", sourceObjectiveStatus = "unverified-source-field" }
quests[11601] = { id = 11601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and Found", description = "Poor Mr. Allerton might yet help us find my brother.\n\n<Leryssa unveils a voluminous book, not unlike an army recruitment ledger.>\n\nI borrowed it, ok?  Let's see, does that enlistment card have a date?\n\nWilliam saw Thassarian at the enlistment line.  Their entries must be near each other... here it is!\n\nHe was assigned to... Unit S?  All the other military units are named after Alliance towns.\n\nWho's in the unit?  Where are they deployed?  We need rumors.  See if the innkeeper's heard anything.", sourceObjective = "Speak to James Deacon at the inn in Valiance Keep.", completion = "Can't say I can help you friend.  But I might know someone who can.", sourceObjectiveStatus = "unverified-source-field" }
quests[11602] = { id = 11602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Off the Source", description = "Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They're keeping the eggs high and dry, away from the epicenter of conflict.\n\nYou're going to have to go back out there and track down their eggs. Find 'em, smash 'em, and trash 'em.\n\nEach egg destroyed means twenty less Nerubians feeding on our corpses.", sourceObjective = "Overlord Razgor at Warsong Hold wants you to destroy 10 Nerub'ar Egg Sacs.", completion = "They just keep on coming, despite our best efforts. Something's gotta give, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11603] = { id = 11603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Wine, Truth", description = "The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline.\n\nHe knows the name of every general, unit, brigade, detachment... you name it.  He's the man you need.\n\nProblem is, his mind is scarred.  He won't talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine.\n\nI haven't received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.", sourceObjective = "Salvage a bottle of Kul Tiras Wine from the underwater shipwreck northeast of Valiance Keep and bring it to Old Man Colburn in the Valiance Keep inn.", progress = "<The old man looks up at you with a blank look on his face.>", completion = "Mmmmm... not too bitter... not too dry... it's just like the old days, with the lads at the barracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11604] = { id = 11604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deserter", description = "Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named after a town...\n\nDarkshire was sent to Dragonblight.  The Goldshire boys were sent to the Fjord.   Where did I hear...\n\nOh, yes... the deserter!  There's a turn-tail in the barracks prison.  Got thrown in not too long ago.  Kept saying that \"S\" stood for suicide.\n\nLook for the deserter.  He might have some information for you.", sourceObjective = "Find the prison inside Inner Hold in Valiance Keep and speak to the deserter.", completion = "Whad'ya want?  I have enough problems as it is!", sourceObjectiveStatus = "unverified-source-field" }
quests[11605] = { id = 11605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Honored Ancestors", description = "<A distant voice echoes in your head as you regard the stone statue.>\n\nDo not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries.\n\nThe quarry has been overrun, leaving many statues unfinished while the ancestors' spirits wander the world. Will you aid me in righting this wrong?\n\nFirst, I must know the names of these wandering ancestors. Look for the markers near their statues.", sourceObjective = "Elder Atkanok outside Coldrock Quarry wants you to identify the statues of Elder Kesuk, Elder Sagani, and Elder Takret.", progress = "<The distant voice returns.>\n\nHave you recovered the names of the wandering elders?", completion = "<Elder Atkanok's voice greets you as you approach his statue.>\n\nWell done, {name}. With the names of the wandering elders, we can continue the ceremonies disrupted during the attack. However, before the elders' spirits can be led to their stones, we must calm the spirits of the murdered craftsmen and shaman. Otherwise, the ancestor spirits may never hear the ceremony's call.", sourceObjectiveStatus = "unverified-source-field" }
quests[11606] = { id = 11606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patience is a Virtue that We Don't Need", description = "We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won't stop coming until we blow their tunnels and passageways up. Of course, we can't do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry.\n\nWe do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.", sourceObjective = "Quartermaster Holgoth at Warsong Hold wants you to recover 15 crates of Warsong Munitions.", progress = "We're running out of time here, {class}.", completion = "If my calculations are correct - and they're often not - you're gonna need about 10-20 seaforium depth charges.\n\nOh yea, you'll be planting these mothers into their sinkholes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11607] = { id = 11607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Spirits", description = "In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we'll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered.\n\nThe aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall.\n\nKill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.", sourceObjective = "Elder Atkanok, on the outskirts of Coldrock Quarry, wants you to free the spirits of 3 Kaskala Craftsmen and 3 Kaskala Shaman.", progress = "How fare the spirits of the innocent?", completion = "I can sense the upheaval in the spirit world beginning to calm. You have done well, {name}. The spirits of the ancestors are fortunate to have your help in this time of need.", sourceObjectiveStatus = "unverified-source-field" }
quests[11608] = { id = 11608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury Those Cockroaches!", description = "North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub'ar sinkholes.\n\n<Holgoth hands you a bundle.>\n\nBe very careful with that package, {name}. Mishandle it and you'll be dog meat.\n\nInside the bundle are seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.\n\nGet a move on!", sourceObjective = "Quartermaster Holgoth at Warsong Hold wants you to use the Seaforium Depth Charge Bundle to destroy the Nerub'ar sinkholes to the south, east, west and north of Warsong Hold.", progress = "Well?", completion = "That'll stop 'em - at least I think it'll stop 'em. Either way, you've done your part. That's all an orc can ask for, no?", sourceObjectiveStatus = "unverified-source-field" }
quests[11609] = { id = 11609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up the Pieces", description = "With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.\n\nThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, {name}, for some are centuries old. You may need to wrest them from the hands of the invaders.", sourceObjective = "Bring 6 Tuskarr Ritual Objects to Elder Atkanok, who stands outside Coldrock Quarry.", progress = "Have you recovered a full set of ritual items?", completion = "<You hold the objects before the statue of Elder Atkanok.>\n\nThose will suffice, although they are in a sad state. Some of them have survived centuries of use, only to be battered and stolen by barbarians.", sourceObjectiveStatus = "unverified-source-field" }
quests[11610] = { id = 11610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading the Ancestors Home", description = "With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala's craftsmen and shaman.\n\nThe ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant.\n\n<Words in a strange language flood your head, but you have no difficulty recalling them.>", sourceObjective = "Elder Atkanok wants you to guide the spirits of Elder Kesuk, Elder Sagani, and Elder Takret to their stone monuments.", progress = "Have you completed the ceremonies for the ancestors?", completion = "The ancestors have found their statues, and they have you to thank, {name}. The craftsmen of Kaskala will return to the quarry and ensure that the line of ancestors continues unbroken. For our part, the ancestors will continue to observe you with interest, as it seems your path is just beginning.", sourceObjectiveStatus = "unverified-source-field" }
quests[11611] = { id = 11611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taken by the Scourge", description = "<Mortuus sighs.>\n\nPeons... We may as well post up a sign offering the Nerub'ar a free meal.\n\nSee, the problem with a peon is that: (1) they're dumber than dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken by the Scourge!\n\nThis puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction.\n\nFind and release my peons, {race}. If they're alive, you'll find 'em spun up in webbing throughout Mightstone Quarry.", sourceObjective = "Foreman Mortuus at Warsong Hold wants you to free 5 Warsong Peons.", progress = "No peons, no buildings. And no, we're not going to replace them with goblins. Too damned expensive...", completion = "Most of them made it back. The ones smart enough to know that we're inside the gigantic metal and stone building, anyway...\n\nRegardless, a job well done. I hear you sprung more than a couple peons loose.\n\nOh yes, you're the talk of the... um... fortress.", sourceObjectiveStatus = "unverified-source-field" }
quests[11612] = { id = 11612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Quarry", description = "You're a welcome sight, {class}. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry.\n\nMy companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau.\n\nWhen they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?", sourceObjective = "Etaruk, camped near the entrance to the Coldrock Quarry, wants you to kill 12 Beryl Treasure Hunters.", progress = "Have you started ridding the quarry of our enemies?", completion = "Now that these strange mages know that the people of Kaskala and their allies will not give up the quarry so easily, we must maintain our efforts and defeat them completely.\n\nMy brothers in Kaskala have also come under attack and will not be able to support us, but with your help, {name}, we can overcome these pillagers.", sourceObjectiveStatus = "unverified-source-field" }
quests[11613] = { id = 11613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karuk's Oath", description = "They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog.\n\nMy village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut.\n\nBy tuskarr law I must seek retribution against those who shed my kin's blood.\n\nI am but a fisherman and I've not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir.\n\nIf you were to carry out my blood duty for me, I will be in great debt to you.", sourceObjective = "Karuk wants you to slay 6 Skadir Raiders and 5 Skadir Longboatsmen.", progress = "Did you succeed, {race}?  The Kvaldir are cruel warriors.  Do not expect any quarter from them.", completion = "You've done my people a great favor, {name}.  I must ask one more thing of you, however.", sourceObjectiveStatus = "unverified-source-field" }
quests[11614] = { id = 11614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untold Truths", description = "We are here by order of Varimathras! The mission of the Shadowstalkers is a simple one: spy. Well, spy with a little assassination on the side.\n\nOne of my best field agents has gone missing. I haven't heard from him in days, which has left me fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... turned traitor even.\n\nHis last known location was northern Mightstone Quarry. He was gathering intelligence on the Nerubians. Find him.\n\nHe better be dead...", sourceObjective = "Find Shadowstalker Luther in Mightstone Quarry.", completion = "It doesn't get much deader than this... Strangely, the Nerubians did not devour the corpse.\n\nAfter careful examination you see that Luther's death was self inflicted - deadly poison. Smart. Nerubians won't come near this toxic corpse.\n\nYou notice that Luther is holding a journal.", sourceObjectiveStatus = "unverified-source-field" }
quests[11615] = { id = 11615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerub'ar Secrets", description = "You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling:\n\nNecrolords. At least a dozen by my count.\n\nFarms to west being used as some sort of horrible spawning glade for Scourge.\n\nRow upon row of victims.\n\nI think they're on to me. Made a dash for the hold. I won't be captured alive.\n\nDreadvenom hemotoxin. If they decide to bite into me, they'll be in for a surprise.\n\nTake this information back to Barthus.", sourceObjective = "Take Luther's Journal to Shadowstalker Barthus at Warsong Hold.", progress = "Is he dead?", completion = "<Barthus flips to the last page of the journal and begins reading.>\n\nThis is very bad news. Hellscream must be notified at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[11616] = { id = 11616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Hellscream", description = "<Barthus tears out the last page and rolls it up.>\n\nTake this to Hellscream at once! In the meantime, I'm going to send a team to scout out the farms.\n\nBe sure to tell Hellscream that we're going to need reinforcements.", sourceObjective = "Take Barthus's Note to Garrosh Hellscream at Warsong Hold.", progress = "What is the meaning of this interruption? Do not burden me with nonsense!", completion = "<Hellscream reads the journal entry.>\n\nIs that all?", sourceObjectiveStatus = "unverified-source-field" }
quests[11617] = { id = 11617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hampering Their Escape", description = "I'm sure you've seen those blue and white platforms hovering over the quarry. They're the transportation the mage hunters used to land their forces here, and now they're loading them up with our artifacts and fragments of our statues.\n\nWe must stop them before they leave the quarry.\n\nThe small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we'll deal with him afterward.", sourceObjective = "Etaruk, outside the Coldrock Quarry, wants you to destroy the North Platform, the East Platform, and the West Platform.", progress = "Have you succeeded in destroying the mage hunters' flying platforms?", completion = "The mage hunters won't find it as easy to plunder our quarry and steal our artifacts as they'd imagined. With your help, we'll win back the quarry and set things right again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11618] = { id = 11618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Incoming...", description = "<Hellscream shakes his head.>\n\nYou may not have noticed that we're trying to win a war here, {race}. I need all available soldiers at the primary points of conflict. This means that we don't have any real soldiers to spare for these minor incursions.\n\n<Hellscream pauses to think.>\n\nIf Barthus wants reinforcements at the farm...\n\n<Hellscream claps his hands together.>\n\n...he shall have them! Report to Barthus's assassins at the farms, west of here. Let them know that reinforcements have arrived.", sourceObjective = "Seek out Shadowstalker Ickoris at the Warsong Farms Outpost west of Warsong Hold.", completion = "This is it? Hellscream sent a single {race} boy?\n\nIf I still had a jaw it would be on the floor right now.", sourceObjectiveStatus = "unverified-source-field" }
quests[11619] = { id = 11619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamel the Cruel", description = "My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.\n\nYou've dealt with his men already.  Finish what you've started, {name}.  Avenge my father and I will share with you what little I still have.", sourceObjective = "Karuk wants you to defeat Gamel the Cruel at Riplash Strand.", progress = "Did you defeat Gamel, {class}?", completion = "You did it, {name}!  The spirits of the slain tuskarr can now rest in peace - their deaths have been avenged!", sourceObjectiveStatus = "unverified-source-field" }
quests[11620] = { id = 11620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Father's Words", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the Kvaldir have kept a naga priestess alive at the temple on the west side of the shore.\n\nShe will no doubt have great reason to resent her uninvited Kvaldir guests.  Perhaps my father is expecting her to cooperate with you in some way.", sourceObjective = "Look for Veehja at the Shrine of Scales on Riplash Strand.", completion = "Hsssssssssssss!  Have you come to mock me, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11621] = { id = 11621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tablet of Leviroth", description = "You scour through the tablet's etchings, looking for any text you can understand.  You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters.  His emissary will then awake.\"\n\nKaruk might be interested in this information.", sourceObjective = "Return to Karuk with the information you found on the tablet.You scour through the tablet's etchings, looking for any text you can understand. You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters. His emissary will then awake.\"\n\nKaruk might be interested in this information.", sourceObjectiveStatus = "unverified-source-field" }
quests[11622] = { id = 11622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Riplash", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests.  Perhaps she can tell you more about what the writing on the tablet means.", sourceObjective = "Find Veehja at the ruins of Riplash in Borean Tundra.There is someone who might shed light on this mystery, {race}. It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests. Perhaps she can tell you more about what the writing on the tablet means.", sourceObjectiveStatus = "unverified-source-field" }
quests[11623] = { id = 11623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit to the Curator", description = "The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I've never seen anything like this curator before.\n\nHe's landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. {name}, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.", sourceObjective = "Etaruk, on the outskirts of the Coldrock Quarry, wants you to kill Curator Insivius.", progress = "Have you done away with the curator?", completion = "The curator and his men must've thought the quarry an easy target for their looting, but you've shown them otherwise, {name}. I am deeply grateful for your help and I'm certain the ancestors will continue to watch over you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11624] = { id = 11624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sky Will Know", description = "I must find out what happened to my master, Farseer Grimwalker!\n\nEarlier, he was observing the magnataur at nearby Magmoth. But one of his grunts just returned, saying that the group had been crushed, and that the farseer was dragged into the depths of the place.\n\nBefore I send you on a suicide mission, I wish to consult with the spirits to learn more.\n\nThere is an air elemental known as Imperean in the ruins of Eldra'nath to the west. She is wise and may give you the information we seek.", sourceObjective = "Speak with Imperean at the Ruins of Eldra'nath.", completion = "You are foolish to come here, little {race}.\n\nWhat is it that you seek?", sourceObjectiveStatus = "unverified-source-field" }
quests[11625] = { id = 11625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trident of Naz'jan", description = "Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen's work!\n\nThey took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace!\n\nI will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!", sourceObjective = "Veehja in Riplash wants you to go to the far northeastern end of the Riplash Ruins. Once there slay Ragnar Drakkarlund and obtain the Trident of Naz'jan from him.", progress = "Do you have the trident?", completion = "Yesssssss!  We will slay the Kvaldir's beast!  I will show these brutes to never cross a priestess of the scale!", sourceObjectiveStatus = "unverified-source-field" }
quests[11626] = { id = 11626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emissary", description = "Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape.\n\nNow you wield it, {race}.  As much as it disgusts me, I will have my revenge on these barbaric giant-men.\n\nTake the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash.\n\nDrive the trident into his flesh and slay him!  Return to whomever sent you when you're done; I wish to see no more of you.", sourceObjective = "Find Leviroth in the waters below the iceberg floating among the northern edge of Riplash Ruins. Use the Trident of Naz'jan to slay him and return to Karuk to the north of Riplash Strand.", progress = "Have you solved the mystery, {name}?  Will my people's spirits be laid to rest?", completion = "My people's spirits can rest in peace.  You've helped me honor my father... perhaps I will one day be as strong as you are.", sourceObjectiveStatus = "unverified-source-field" }
quests[11627] = { id = 11627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boiling Point", description = "Ah, it is information that you crave: the whereabouts and condition of your 'farseer'. He did not see so far as to avoid the trouble which befell him.\n\nNevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me.\n\nNo doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn's pool, and the two have been battling for ages.\n\nGo to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.", sourceObjective = "Imperean wants you to beat Simmer and Churn into submission. Return to her at the Ruins of Eldra'nath when they have submitted.", progress = "You still have yet to beat some sense into those two.", completion = "I am pleased, though no doubt they will still continue to quarrel a bit longer.\n\nHowever, there is something else that you will need to accomplish before you can return to your spirit talker.", sourceObjectiveStatus = "unverified-source-field" }
quests[11628] = { id = 11628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouds of the Scourge", description = "To the northeast looms the Temple City of En'kilah, the Scourge's seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us.\n\nRemaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth.\n\nThe Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.", sourceObjective = "Chieftain Wintergale at Taunka'le Village wants you to bring him 5 Scourged Mammoth Pelts.", progress = "Have you brought the mammoth pelts?", completion = "As much as I dislike bringing such disease-ridden things into the village, they may give us an advantage over our foes.\n\n<The chieftain gestures to Sage Aeire and waves dismissively at the pelts.>\n\nWhile she is preparing the pelts, there is one other element we need to create the cloak.", sourceObjectiveStatus = "unverified-source-field" }
quests[11629] = { id = 11629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Spirit Talker", description = "You have done what was asked, and now I give you that which you desire.\n\nDeliver this primal to the spirit talker back at your Bor'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.", sourceObjective = "Deliver Imperean's Primal to Spirit Talker Snarlfang at Bor'gorok Outpost.", progress = "{name}, you have returned. What did you learn?\n\nWhat is that sound?", completion = "Imperean gave you a primal essence of herself? I can hear its howling winds!\n\nI know a ritual we can make use of it in. We must hurry before her primal rips itself apart!", sourceObjectiveStatus = "unverified-source-field" }
quests[11630] = { id = 11630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad Earth", description = "By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says.\n\nShe'd best be correct. It's our only chance to gather information and plan our counterattack.\n\nYou should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you've finished gathering it.", sourceObjective = "Bring 8 clods of Scourged Earth to Chieftain Wintergale at Taunka'le Village.", progress = "Do you have the earth Sage Aeire needs to complete the cloak?", completion = "<Chieftain Wintergale gingerly accepts the clods of soil you gathered.>\n\nWe should get these into Sage Aeire's hands as soon as possible.\n\n<The chieftain grunts, pretending not to be disturbed by the tainted dirt.>\n\nWe can never know when the Scourge commander will launch the final assault on the village.", sourceObjectiveStatus = "unverified-source-field" }
quests[11631] = { id = 11631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision of Air", description = "Here, {name}, I've attuned the primal to you.\n\nOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.\n\nThe spirit of the wind touches all; with any luck you will be granted a vision.", sourceObjective = "Use Imperean's Primal to perform a ritual at Snarlfang's Totem at Bor'gorok Outpost to gain information concerning Farseer Grimwalker.\n\nAfterward, speak with Spirit Talker Snarlfang.", progress = "When you feel that you have seen enough, return the primal to me.", completion = "They've shackled his spirit. {name}, we have to put an end to his torture!\n\nYou must descend into the bowels of Magmoth and find a way to free him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11632] = { id = 11632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Cold Wind Brings...", description = "You hold the carapace fragment of Ith'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde.\n\nTake your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.", sourceObjective = "Take Ith'rix's Hardened Carapace to High Overlord Saurfang at Warsong Hold.", progress = "What have you got there?", completion = "<Saurfang grins.>\n\nIt looks familiar... The Might of Kalimdor trampled a thousand bugs like this one in the desert of Silithus.\n\nThis is a different place - a different environment - but the result will be the same.\n\n<Saurfang looks you over.>\n\nYou will bring pride and honor to the Horde in Northrend, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11633] = { id = 11633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blending In", description = "Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy's fortifications and leaders.\n\nWhile wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En'kilah abominations will be able to find you if you get too close.", sourceObjective = "Chieftain Wintergale at Taunka'le Village wants you to wear the Imbued Scourge Shroud in the Temple City of En'kilah and scout the Spire of Blood, the Spire of Pain, and the Spire of Decay.", progress = "Have you finished scouting the temples in the Scourge's fortress?", completion = "<Chieftain Wintergale listens as you describe your observations.>\n\nThe information you've gathered will help us to plan our assault on the Temple City. We'll need to find a way to defeat the officers you identified and get into that necropolis.", sourceObjectiveStatus = "unverified-source-field" }
quests[11634] = { id = 11634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wind Master To'bor", description = "You're a tough mother, {name}. I think your talents are better suited elsewhere - like the root of the whole damn problem!\n\n<Razgor points to the west.>\n\nA thousand Scourge, at least four full sized floating death machines and who knows what else.\n\nBut you're gonna find out and then you're gonna handle it... That's right, you're gonna beat the hell out of the Scourge army that's currently beating down our door.\n\nGet to the top of Warsong Hold and report to Wind Master To'bor. He'll be expecting you.", sourceObjective = "Report to Wind Master To'bor at Warsong Hold.", completion = "Ay, mon. I been expectin' you.\n\n<To'bor points west.>\n\nTake a peek. Across dat tundra be death, mon... death.", sourceObjectiveStatus = "unverified-source-field" }
quests[11635] = { id = 11635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farseer Grimwalker's Spirit", description = "You must go to Magmoth to the east.\n\nYou must descend into the depths of their caverns.\n\nYou must speak with Farseer Grimwalker's spirit!", sourceObjective = "Speak with Farseer Grimwalker's Spirit inside of Magmoth.", completion = "Thank you for the reprieve, {class}. If only my true freedom were so easy to attain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11636] = { id = 11636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Carpet Ride", description = "Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da tank to lay down some Horde justice on da Scourge!\n\nDa only tricky part be getting' you der. No way we be sendin' you on our wind riders. Too risky.\n\nYou see dat pixie o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. Once der, talk to Annihilator Grek'lor!", sourceObjective = "Talk to Yanni at Warsong Hold to arrange safe travel to the coast. Speak to Annihilator Grek'lor once you arrive at Garrosh's Landing.", completion = "NO MERCY FOR THE DEAD!\n\nNone of 'em had the guts to stay behind to defend our glorious tanks after Hellscream deemed the coast 'condemned.' It's mostly quiet here, seein' as how the Scourge are formin' up ranks to assault Warsong Hold. Sometimes I get a stray zombie or ghoul, but they don't last very long.\n\n'Course, there's the mist...\n\n<Grek'lor shudders.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11637] = { id = 11637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaganishu", description = "After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu.\n\nThough you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism.\n\nYou must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves.\n\nOnly then will I truly be free.", sourceObjective = "Retrieve Kaganishu's Fetish and use it upon Farseer Grimwalker's Remains.\n\nYou will need to give the fetish to Farseer Grimwalker's Spirit inside of Magmoth.", progress = "Hurry, {class}, use the fetish upon me before it is too late.", completion = "I am freed. Thank you, {name}.\n\nAnd now, I have one final request of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11638] = { id = 11638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return My Remains", description = "{name}, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.\n\nI sense that the spirit talker is still at Bor'gorok Outpost to the west where last I saw her.", sourceObjective = "Deliver Farseer Grimwalker's Remains, which are resting below his spirit, to Spirit Talker Snarlfang at Bor'gorok Outpost.", progress = "You return sooner than I expected. What did you learn?", completion = "Thank you for freeing his spirit from Kaganishu and returning with his remains. We have little to reward you with, but you may take whatever catches your eye.\n\nAnd now, I will return him to the living where he belongs.", sourceObjectiveStatus = "unverified-source-field" }
quests[11639] = { id = 11639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge Upon Magmoth", description = "The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure.\n\nBut you could get revenge for me and the others who fell at Magmoth!\n\nI know that the spirit talker wants you to go in there to save the farseer.\n\nIt's just to the east. Go, {class}... go slay the magnataur and their snobold servants. Regain the outpost's honor!", sourceObjective = "Kill 10 Magmoth Shaman, 5 Magmoth Foragers, 3 Magmoth Crushers, and 3 Mates of Magmothregar. Then, return to Ortrosh at Bor'gorok Outpost.", completion = "The dead are honored by your actions, {name}.\n\n\n\nPerhaps now I can find my way back to being the warrior I once was.", sourceObjectiveStatus = "unverified-source-field" }
quests[11640] = { id = 11640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Power", description = "Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.\n\nAn endless stream of Scourge minions will overrun us if we can't find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, {name}, to slay the high priests and take the scrolls they hold.", sourceObjective = "Bring High Priest Naferset's Scroll, High Priest Talet-Kha's Scroll, and High Priest Andorath's Scroll to Chieftain Wintergale at Taunka'le Village.", progress = "We must get into that necropolis if we're to break through the Scourge and clear a path for the villagers.", completion = "<Chieftain Wintergale reads the words written on the scrolls.>\n\n'Shabtir bakh sokhen.'\n\nWords of the ancient, harsh language used by the Nerubians, and apt ones at that.\n\n'The servant bows to the master's authority.' These are the words that will gain you entry into the necropolis.", sourceObjectiveStatus = "unverified-source-field" }
quests[11641] = { id = 11641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Courageous Strike", description = "From the beginning, I've counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he'd rather tip-toe around according to Sage Aeire's plans.\n\nI'll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you'd be willing to show him that a direct attack can succeed. Storm the Temple City of En'kilah and slay all in your path, {name}.", sourceObjective = "Slay 15 En'kilah Ghouls and 5 En'kilah Necromancers and report back to Durm Icehide at Taunka'le Village.", completion = "You have proven your fearlessness and demonstrated your prowess in combat. I believe you would make a fine taunka warrior. I only wish the chieftain had the same understanding.\n\nWe are fortunate to count you as an ally in our struggle to evacuate the village before it is overrun by the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[11642] = { id = 11642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank Ain't Gonna Fix Itself", description = "We need to get these tanks back up and runnin'! They ain't gonna fix themselves. Mobu's gonna be the one to handle that stuff. Talk to him and see what he needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and I cleave him in two!", sourceObjective = "Speak with Mobu at Garrosh's Landing.", completion = "You're the new tank driver, buddy? Fine by me! We just need to get these things up and running again. Yea, you try to go out into the Plains of Nasam without a tank and you're as good as dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11643] = { id = 11643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobu's Pneumatic Tank Transjigamarig", description = "These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It's the beat down hut next to the stables. You're gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist.\n\nOh yea, buddy, watch out for the mist. The mist is what tore up these shores.", sourceObjective = "Mobu at the Coast of Echoes in the Borean Tundra wants you to recover his Pneumatic Tank Transjigamarig.", progress = "Did you find the P.T.T.?", completion = "Great work, buddy! Now where'd I put those spare parts...", sourceObjectiveStatus = "unverified-source-field" }
quests[11644] = { id = 11644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Strong Metal Plates!", description = "I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh's Landing and at the bottom of the bay.\n\nJust be careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...", sourceObjective = "Mobu at the Coast of Echoes in the Borean Tundra wants you to collect 10 Super Strong Metal Plates.", progress = "Remember, the mist is bad!", completion = "Great work, buddy! Now where'd I put that pneumatic tank transjigamarig.", sourceObjectiveStatus = "unverified-source-field" }
quests[11645] = { id = 11645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty, Stinkin' Snobolds!", description = "Those dirty, stinkin' snobolds... they stole all of my supplies!\n\nWhat's a snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of them. I know, weird!\n\nAnywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the north side of the airstrip.\n\nWhy don'tcha do me a favor and head north to their stupid Magmoth. There's a cash reward if you bring all my stuff back quick!", sourceObjective = "Retrieve 10 boxes of Crafty's Stuff and return them to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Ya got all of my supplies, {class}? I just can't do ANYTHING without all of my stuff!", completion = "Oh, {name}, you're just the best!\n\nHere's your coin as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[11646] = { id = 11646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Borean Inquisition", description = "Listen closely, {name}, for there is not a moment to spare.\n\nYour prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required.\n\nMake your way up to where he is being detained and tell Librarian Normantis that I've sent you to assist him.", sourceObjective = "Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge.", completion = "It was wise of Donathan to send you, {class}.\n\nAs it turns out, I am in need of someone outside the Kirin Tor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11647] = { id = 11647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Cauldrons", description = "The presence of plague cauldrons within the Temple City of En'kilah worries me greatly, {name}. It's clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?\n\nI've prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.", sourceObjective = "Sage Aeire at Taunka'le Village wants you to use her totem to neutralize the East Cauldron, the Central Cauldron, and the West Cauldron in the Temple City of En'kilah.", completion = "<Sage Aeire accepts the totem from you.>\n\nDid the totem work? Its preparation required ancient magics the sages haven't used in generations. Of all the knowledge passed down, only a fraction of it remains in use today.", sourceObjectiveStatus = "unverified-source-field" }
quests[11648] = { id = 11648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Persuasion", description = "It is fortunate you're here, {race}.\n\nYou see, the Kirin Tor code of conduct frowns upon our taking certain 'extreme' measures - even in desperate times such as these.\n\nYou, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information.\n\nDo what you must. We need to know where Lady Evanor is being held at once!\n\nI'll just busy myself organizing these shelves here. Oh, and here, perhaps you'll find this old thing useful....", sourceObjective = "Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor.", progress = "Well? Do you know where Lady Evanor is being held?", completion = "Excellent! It was crucial that we collect that intelligence.\n\nWell done, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11649] = { id = 11649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motes of the Enraged", description = "Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker.\n\nAs you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage.\n\nIn order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.", sourceObjective = "Obtain 5 Tempest Motes and deliver them to Imperean at the Ruins of Eldra'nath.", progress = "Once you have the necessary motes, I will combine a portion of my essence with theirs. The result will get you what you need.", completion = "I regret the loss of those tempests, but my word is my bond... even to a mortal such as yourself.\n\nNow, let us see if we can fashion something of use to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11650] = { id = 11650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Few More Things...", description = "As you may have noticed, we created the airstrip on the southern border of a magnataur den!\n\n<Crafty says something uncharitable about Fizzcrank under her breath.>\n\nThe old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb!\n\nThat's where you come in. I want you to get me everything on this shopping list. Please.", sourceObjective = "Collect Crafty's Tools, an Overcharged Capacitor, and a Handful of Rocknar's Grit. Deliver them to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Why is it that I don't believe you've collected everything on my list?", completion = "Alright, that's more like it! Now all we gots to do is put all this together.\n\nYeah, as if you're going to help me with that.\n\nHold your horses, this'll just take a second now that I've got my tools back!", sourceObjectiveStatus = "unverified-source-field" }
quests[11651] = { id = 11651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanks a lot...", description = "Thanks for all your help, buddy. You can let Grek'lor know the tanks are ready for action. Hopefully you can clean up this place once and for all!", sourceObjective = "Speak to Annihilator Grek'lor at the Coast of Echoes.", completion = "With the current state of our transports and shipping lanes, we haven't been able to get a damned siege engine to Warsong. These tanks are all that we have left from the original expedition. Now that they're operational, you're gonna use 'em to stomp the Scourge offensive at the Plains of Nasam.", sourceObjectiveStatus = "unverified-source-field" }
quests[11652] = { id = 11652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plains of Nasam", description = "Once you're ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here.\n\nUse the tank's weapon arsenal to take down the Scourge army. If you get in a jam, the \"Meatpounder\" will tear 'em up and the land mines will finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks can be found all over the field.\n\nTry to get close enough to that structure in the center and see what's going on.\n\nIf you do all of this and live, go to Hellscream!", sourceObjective = "Use the Horde Siege Tank to destroy 100 Scourge Soldiers and rescue 3 Injured Warsong Soldiers on the Plains of Nasam. You must also discover the identity of the leader of the Scourge assault.\n\nReport to Garrosh Hellscream at Warsong Hold should you succeed.", completion = "Kel'Thuzad? So it's true - Naxxramas returns...\n\nPerhaps I underestimated you, {name}. You've done the Horde a great service. The Warchief would be proud!\n\n\n\nIf Kel'Thuzad is controlling these Scourge, there's no telling what else the Lich King has in store for us... I'll need time to think through this new information, {name}. You are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11653] = { id = 11653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hah... You're Not So Big Now!", description = "That'll do her, chief! So, here's what I want ya to do....\n\nTake my blaster and head north to Magmoth. If we're gonna have a chance at all against those monsters, we need to cut them down to size... so to speak.\n\nIn order to gauge its effectiveness, I need you to slay the magnataur while the blaster's effects are still on it. Any of the crushers or mates will do, but don't bother with the offspring... they're too small to worry about.", sourceObjective = "Test out Crafty's Ultra-Advanced Proto-Typical Shortening Blaster on 5 Magmoth Crushers or Mates of Magmothregar. After you have done so, return to her at Fizzcrank Airstrip.", completion = "Whadya mean it didn't work?!\n\nBut... but...\n\n<Crafty begins to sob.>\n\nOkay, we can deal with this. I'm a big girl. Time to think outside the box!", sourceObjectiveStatus = "unverified-source-field" }
quests[11654] = { id = 11654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spire of Blood", description = "As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive.\n\nWhat use would the Scourge have for blood? They've never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you'll be able to discover what the Scourge is planning.", sourceObjective = "Search the Spire of Blood for more information about the Vial of Fresh Blood.", progress = "How... how did you find me?", completion = "<The taunka snow tracker appears weak and barely responds to you.>\n\nI haven't... long. Maybe... maybe you can stop them... before...", sourceObjectiveStatus = "unverified-source-field" }
quests[11655] = { id = 11655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mist", description = "Across the mist to the north you will find Garrosh's Landing. To the south are the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as the Kvaldir.\n\nThese fearsome savages slew all of my people without mercy and drove your people inland.\n\nAll that remains of the tuskarr of Pal'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to kill Kvaldir and recover 8 Tuskarr Relics.", progress = "By blood and honor you must serve... Return the tuskarr relics.", completion = "<Sadness overcomes Waltor.>\n\nRuin... That is all they leave in their wake. They must be taught a lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[11656] = { id = 11656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn in Effigy", description = "Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable.\n\n<Waltor waves a torch-like baton in front of you.>\n\nWith this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh's Landing, north of here, and one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all to see!", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Tuskarr Torch to burn the Kvaldir ships at Pal'ea and Garrosh's Landing. You must destroy the following ships: The Serpent's Maw, The Kur Drakkar, Bor's Hammer and Bor's Anvil.", progress = "Is it done? Are the ships ablaze?", completion = "A show of resistance to the Kvaldir savages might be what is needed to save my people at the other encampments. Perhaps the Kvaldir will rethink their actions should they believe that retribution will come.", sourceObjectiveStatus = "unverified-source-field" }
quests[11657] = { id = 11657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.\n\nCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!", sourceObjective = "Catch 4 torches in a row, then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11658] = { id = 11658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plan B", description = "Okay, don't panic! The blaster might not've worked, but we still have options.\n\n<Crafty snaps her fingers.>\n\nWe're going to divert attention away from the airstrip! To make this work, we'll need a few things first.\n\n<Wobblesprocket looks you up and down appraisingly.>\n\nSteeljaw's caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits.\n\nHead over there and get some outfits off of the dead orcs. Pick up one of their banners, too!", sourceObjective = "Collect 10 Warsong Outfits and a Warsong Banner. Bring them back to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "We'll need lots of their clothes if this is going to work. I'm no seamstress... we'll just have to find something to fit you!\n\nAnd then I'll just add a touch of my engineer genius, and poof, you'll look the part you need to play.", completion = "Nice, but those clothes reek!\n\nPersonally, you'd never catch me dead in such rags. But we're going to have to sort through them and find some that fit your, um... figure.", sourceObjectiveStatus = "unverified-source-field" }
quests[11659] = { id = 11659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Orbs!", description = "They're... bleeding the prisoners... putting the blood... in those globes.\n\n<Grumm's eyes close momentarily and he leans his head back.>\n\nThe blood... taken up to necropolis... to feed blood prince...\n\n<Grumm gasps for breath.>\n\nP-promise... you'll... destroy blood... globes... bring word... to Junek.\n\n<The snow tracker collapses into unconsciousness.>", sourceObjective = "Destroy 5 Blood Globes and report to Snow Tracker Junek at Taunka'le Village.", completion = "I feared they might've captured Grumm, but I never thought they'd do such horrific things to him. I've never seen a warrior survive a losing battle with the Scourge.\n\nThank you for bringing word of his fate, {name}. He was a mighty warrior and we will remember him as such.", sourceObjectiveStatus = "unverified-source-field" }
quests[11660] = { id = 11660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn of the Ancient Mariner", description = "A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal'ea, He oversaw the destruction of both villages and then disappeared into the mist.\n\nIn those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise.\n\nWe need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat.\n\nSeek out mistweavers at Pal'ea, to the south.", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to bring him the Horn of the Ancient Mariner.", progress = "Find the Horn of the Ancient Mariner!", completion = "You must call for Orabus using the Horn of the Ancient Mariner.", sourceObjectiveStatus = "unverified-source-field" }
quests[11661] = { id = 11661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orabus the Helmsman", description = "Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus.\n\nSlay the foul beast and return to me!", sourceObjective = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Horn of the Ancient Mariner to summon Orabus the Helmsman. Once summoned, slay Orabus the Helmsman.", progress = "Orabus must be destroyed!", completion = "It seems that the loss of their lieutenant has only stirred the nest. They are more angry and aggressive than before!\n\n<Waltor sighs.>\n\nYou've done what you can here, friend. At the very least you deserve some form of compensation for thinning their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[11662] = { id = 11662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Karuk!", description = "A fellow survivor of Pal'ea known as Karuk has made his way to the main base of the Kvaldir in the Borean Tundra - far to the south where the snow was once bountiful. Karuk hides along the bluffs overlooking Riplash Strand.\n\nSeek out Karuk and let him know what you did for my people here at the Coast of Echoes.\n\nThe safest route to Karuk is through your fortress. From Warsong Hold, take the road south and follow it around until you reach Riplash Strand.", sourceObjective = "Seek out Karuk at Riplash Strand.", completion = "Waltor was wise in sending you to me, {race}. The gods smile down upon those that mete justice. You will be he that doles out punishment to the wicked!", sourceObjectiveStatus = "unverified-source-field" }
quests[11663] = { id = 11663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing Intelligence", description = "Thank you, {class}! The information you've extracted is of vital importance to the Kirin Tor.\n\nReturn at once to Donathan as we make plans for the rescue of Lady Evanor.", sourceObjective = "Normantis has asked you to report to Librarian Donathan on Amber Ledge.", completion = "Forgive me, {name}. I know that was unpleasant work.\n\nWere it not for the desperation of our circumstance I'd never have asked you to assist us in such a manner.\n\nSo... what have you discovered?", sourceObjectiveStatus = "unverified-source-field" }
quests[11664] = { id = 11664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaping the Mist", description = "I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others?\n\nI wonder, how far has the mist crept, stranger? Has it overtaken this whole continent?\n\nWould you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.", sourceObjective = "Follow Mootoo the Younger out of the mist. Speak to Elder Mootoo should you successfully save Mootoo the Younger.", progress = "You found my daughter?", completion = "It is whispered in the winds, friend. Your name is known to the elements. You have done a great service to Mootoo on this day and you shall be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[11665] = { id = 11665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisks in the City", description = "Hello <lad/lass>.  I'm glad you've stopped by to talk to this old man--there's trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.", sourceObjective = "Bring a Baby Crocolisk to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Catch any crocs in the sewers yet?", completion = "What a mean little creature!  I'm sure the Rokk will make something tasty with him.\n\nI'm just kidding, of course.\n\n<Old Man Barlo winks slyly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11666] = { id = 11666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait Bandits", description = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.", sourceObjective = "Bring a Blackfin Darter to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "How's the fishing today, lad?", completion = "Well look at that... you caught a big one!  This old man is eating in style tonight.", sourceObjectiveStatus = "unverified-source-field" }
quests[11667] = { id = 11667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.\n\nYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", sourceObjective = "Catch the World's Largest Mudfish and bring it to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Tell me you caught him.  Please tell me you caught that son of a carp.", completion = "There he is!  I'd know that scar anywhere.\n\nTo be completely honest, I thought he'd be... bigger.  Well, I suppose I'll let him go and try again another day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11668] = { id = 11668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrimpin' Ain't Easy", description = "There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?\n\nShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", sourceObjective = "Bring 10 Giant Freshwater Shrimp to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "What's the catch of the day, lad?", completion = "You are skilled with both the hook and knife.  Hand those sweet tidbits over, and I'll let you have a taste.", sourceObjectiveStatus = "unverified-source-field" }
quests[11669] = { id = 11669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felblood Fillet", description = "This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.", sourceObjective = "Bring a Monstrous Felblood Snapper to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "The felblood is a marvel of evolution.  It can survive in any water and even lava, and fishermen are its only natural predator.\n\nAny luck with your prey?", completion = "That is the biggest, ugliest fish I've seen.  I can't even imagine what you used for bait.\n\nJust set the beast on the ground, and I'll deal with it once I'm sure it's dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11670] = { id = 11670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Was The Orcs, Honest!", description = "With all of those outfits you, er, recovered, I fashioned a Warsong orc disguise. I had the genius idea of combining it with some old stuff that I had left hanging around from last Hallows' End, so it should be foolproof!\n\nHere, in this sack is the disguise and the banner you recovered. Head down into the bowels of Magmoth and slay the magnataur chieftain, Magmothregar.\n\nIf you're going to convince them to turn their attention on the Warsong orcs, you'll need to plant the banner while disguised.", sourceObjective = "While disguised as a Warsong orc, plant the Warsong Banner in the corpse of Magmothregar. Then, return with the disguise to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "It's all over then? You've done the dirty deed and framed the orcs at Bor'gorok Outpost?", completion = "Holey moley, you did it!\n\nAlright, now those pesky magnataur and their snobold flunkies should turn their attentions on the Horde.\n\nHow can I ever repay you, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11671] = { id = 11671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Race Against Time", description = "So it's true. They have her.\n\nIt's clear what must be done, {race}. She WILL be saved.\n\nI must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact.\n\nWe've customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you've collected the key.\n\nHurry, {name}. Lady Evanor is suffering!", sourceObjective = "Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds.", progress = "Have you collected Salrand's key?", completion = "Broken? \n\nLet me have a look....", sourceObjectiveStatus = "unverified-source-field" }
quests[11672] = { id = 11672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlistment Day", description = "You've come to enlist, right?  Normally you'd have to stand in line like the other recruits.  Normally you'd be out of luck because the recruitment ledger's gone missing and I can't process anyone until the new books get here.\n\nFortunately for you, {name}, I've heard about you and what you did in Outland.  To be honest, you're a cut above these poor saps.  Lines aren't for you.\n\nGo to the barracks and speak to General Arlos.  He'll be more than happy to meet with someone of your caliber.", sourceObjective = "Meet with General Arlos inside the barracks in Valiance Keep.", completion = "We've been expecting your arrival, {name}.  Welcome to Northrend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11673] = { id = 11673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Outa Here!", description = "I knew they'd send someone for me sooner or later... turned out to be later, of course.\n\nI came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I'd make a tasty snack for Magmothregar.\n\nWait... what?! They didn't send you?!\n\nDID THEY FORGET ABOUT ME?!\n\nOkay, you're here now and that's all that matters.\n\nAs soon as you break this chain we'll make our way back to the airstrip. Then you can tell Fizzcrank I'm safely back.\n\nIf he remembers me, that is.", sourceObjective = "Escort Bonker Togglevolt to safety and then report in with Fizzcrank Fullthrottle at Fizzcrank Airstrip.", completion = "Huh? What?\n\nBonker who?\n\nI've no idea who you're talking about, but I'll take your word for it. If you rescued him or her from the pit of Magmoth then I suppose you deserve a reward.\n\nLet me see what I've got lying around in here....", sourceObjectiveStatus = "unverified-source-field" }
quests[11674] = { id = 11674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage Highmesa is Missing", description = "There are many new mysteries walking the lands now. One of our sages, Highmesa, has foolishly gone north with only one longrunner to investigate something strange near the Dens of Dying.\n\nWhat are the dens, you ask? They are a sacred place to the magnataur, where they go in their old age to die. She saw something fall from the sky near them a few days ago.\n\nIf you would be friend to the taunka, I would have you find and help her. She is not so stubborn that she will not accept your aid.", sourceObjective = "Find Sage Highmesa near the Dens of Dying.", completion = "The greatmother sent you. She must be disappointed in me.\n\nBut when I saw the great object fall from the sky, I could not wait for a full group of longrunners and snow trackers to accompany me. Knowledge waits for no one.", sourceObjectiveStatus = "unverified-source-field" }
quests[11675] = { id = 11675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Death", description = "The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery.\n\n{race}, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.", sourceObjective = "Destroy 10 Plagued Magnataur and then return to Sage Highmesa south of The Dens of Dying.", completion = "What else can we do but ease their suffering? In any case, they came here to die, so do not mourn them. At least you have given them some dignity.\n\nNow we must put an end to that which is causing the plague.", sourceObjectiveStatus = "unverified-source-field" }
quests[11676] = { id = 11676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merciful Freedom", description = "The soldiers that they didn't kill are being held in cages scattered across this farmland. Through some thievery we've managed to find a few keys, but we're unable to get close enough to any prisoners without being attacked.\n\nWe need your \"talents\" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.", sourceObjective = "Shadowstalker Canarius at Warsong Farms Outpost wants you to free 5 Scourge Prisoners.", progress = "Save those prisoners!", completion = "Each prisoner saved is one less undead aberration that we have to deal with, {name}. You've done a great service for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11677] = { id = 11677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Plague", description = "I'm convinced that the plague is being caused by something in the caves up there.\n\n{class}, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens.\n\nFind the source of the plague and throw them into it.", sourceObjective = "Sage Highmesa, standing just south of The Dens of Dying, has asked you to use Highmesa's Cleansing Seeds at a Den of Dying Plague Cauldron to neutralize it.", progress = "Either cave should do, {class}. Quickly, use the seeds to end the plague!", completion = "<The sage hangs her head and sighs in relief.>\n\nThis is a good start. If only that were our only problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[11678] = { id = 11678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Bristlehorn", description = "Bristlehorn should have returned by now.\n\nThe other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He's impetuous and has likely gotten himself into trouble.\n\n{name}, go to that place and find him, please.", sourceObjective = "Find Longrunner Bristlehorn at Talramas.", completion = "I am... not... long for this... world, little {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11679] = { id = 11679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging the Key", description = "Delays, delays... the one thing we cannot afford right now!\n\nAs much as I hate to disturb Lord Surristrasz, he's our only hope of saving our beloved Evanor.\n\nBring him the key fragments and hope that his mood is favorable.\n\nHurry, {class}, our assault team is waiting.", sourceObjective = "Donathan wants you to speak to Surristrasz on Amber Ledge.", progress = "You dare approach me, mortal?\n\nFor the sake of your unborn children, pray that your cause is worthwhile.", completion = "The frivolous games you play here are of no consequence....\n\nYou and your Dalaran allies pick at loose threads while the fabric of this world's future is being shredded.\n\nStill, this may provide my drakes some needed amusement.\n\nShow me this key....", sourceObjectiveStatus = "unverified-source-field" }
quests[11680] = { id = 11680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Wing", description = "The key is forged anew.\n\nNow heed my counsel, {race}. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable.\n\nNow, off with you.", sourceObjective = "Give Salrand's Key to Warmage Anzim when you are ready to free Evanor.\n\nProvided item:", completion = "This is it, the key is ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[11681] = { id = 11681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing Evanor", description = "At last, we attack!\n\nOnce we've cleared the platform I'll use the key.\n\nYou are to ensure that Lady Evanor remains safe after her release.\n\nHurry now, let us be off!", sourceObjective = "Anzim on Amber Ledge wants you to fly with his war mages to free Lady Evanor at Beryl Point. You are then to report to her in the mage tower on Amber Ledge.", completion = "Your heroic efforts shall not be forgotten, {class}.\n\nPlease, accept this with my sincere gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11682] = { id = 11682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonspeak", description = "I am aware of your recent deeds here, {name}, and again I thank you.\n\nAs for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues....\n\nAzeroth needs you. The region just west of here is the center of an urgent crisis.\n\nI'll leave the details to Lord Surristrasz. You must speak with him at once.\n\nGood luck, friend of Dalaran.", sourceObjective = "Lady Evanor has sent you to speak with Surristrasz on Amber Ledge.", completion = "So, {race}, we speak again.\n\nWhen you've heard my words you may wish we had not.", sourceObjectiveStatus = "unverified-source-field" }
quests[11683] = { id = 11683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Necropolis", description = "The fallen necropolis to the west can only be assumed to still be filled with Scourge.\n\nWhile you are at Talramas, {class}, I would ask that you dispatch all of the Lich King's servants that you find within and in the surrounding pools where it fell.", sourceObjective = "Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Sage Highmesa just to the south of The Dens of the Dying.", completion = "Thank you, {name}.\n\nThe Lich King and his Scourge are a blight upon Northrend. We must not stop until they are all truly dead, and his existence is put to an end!", sourceObjectiveStatus = "unverified-source-field" }
quests[11684] = { id = 11684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Sinkholes", description = "Can you feel the tremors in the earth?\n\nThe Scourge's nerubians are on the move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out.\n\n<The taunka elder offers you a worn map.>\n\nPerhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.", sourceObjective = "Greatfather Mahan at Taunka'le Village wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.", progress = "Have you marked the locations of the sinkholes?", completion = "<Greatfather Mahan accepts the map, but makes no move to examine it..>\n\nWe'll be able to use your information later, once we're prepared to carry out the plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[11685] = { id = 11685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Elements", description = "Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help.\n\nSoutheast of the village, near the coast beyond the Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.", sourceObjective = "Bring 5 Elemental Hearts to Wind Tamer Barah at Taunka'le Village.", progress = "Greatfather Mahan tells me you have agreed to help collapse the tunnels.", completion = "These should be enough to form the core of a mighty elemental, but stone alone will not give my elemental life.", sourceObjectiveStatus = "unverified-source-field" }
quests[11686] = { id = 11686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warsong Farms", description = "According to Luther's notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field.\n\n<Ickoris shudders.>\n\nThose monsters were once orcs... tauren...\n\nWe need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west of us, and the old Warsong Slaughterhouse, north of us.\n\nReturn to me once you've scouted 'em out.", sourceObjective = "Shadowstalker Ickoris at Warsong Farms Outpost wants you to scout Warsong Granary, Torp's Farm, and Warsong Slaughterhouse.", progress = "Have you searched the farms?", completion = "This is far worse than what was noted in Luther's journal. They've got this place covered in Scourge and are infecting everything they touch.\n\n<Ickoris nods.>\n\nIt gets worse - if you can imagine such a thing...", sourceObjectiveStatus = "unverified-source-field" }
quests[11687] = { id = 11687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doctor and the Lich-Lord", description = "There are two... that must... be killed.\n\nThe doctor and... the lich-lord... are above. Find them... destroy them... before....\n\n...it is too... late....", sourceObjective = "Destroy Doctor Razorgrin and Lich-Lord Chillwinter. Then, return to Sage Highmesa just to the south of The Dens of Dying.", completion = "Bristlehorn is dead?!\n\nI should never have let him go there by himself.", sourceObjectiveStatus = "unverified-source-field" }
quests[11688] = { id = 11688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damned Filthy Swine", description = "Just look at 'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, {race}. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off 'em, else there'll be nothin' left to cure!\n\nGet out there and send those swine to their graves - permanently!", sourceObjective = "Farmer Torp at Warsong Farms Outpost wants you to kill 10 Unliving Swine.", progress = "I need more time! Keep those swine off my kodos!", completion = "I think I've got it, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11689] = { id = 11689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return with the Bad News", description = "The greatmother will need to know, {name}.\n\nWill you please return to Taunka'le? Tell her that I will be following shortly.", sourceObjective = "Speak with Greatmother Taiga at Taunka'le Village.", completion = "What word do you bring from Highmesa?\n\n<You explain what you know and give the greatmother the bad news concerning Longrunner Bristlehorn.>\n\nMy... my grandson!\n\n<The greatmother fights to keep control of her emotions.>\n\nHe died an honorable death like a true taunka!\n\nYou were the last to be with him, {name}, so he shall always be a part of you. I give you my thanks for completing his last wishes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11690] = { id = 11690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring 'Em Back Alive", description = "Take this riding snaffle, {name}. You'll notice that I've placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. They'll be weak so you'll need to gently direct 'em here.\n\nBring my babies back, {name}!\n\nOne last thing, you've got ten minutes! That's how long the antidote will remain effective inside that snaffle.", sourceObjective = "Farmer Torp at Warsong Farms Outpost wants you to rescue 8 Infected Kodo Beasts.", progress = "Get them out of those Scourge infested fields!", completion = "You're a true hero, {name}. My kodos would have died out there without you. You have my thanks and the thanks of all the soldiers and journeymen that will use these kodos to strengthen our presence in Northrend!", sourceObjectiveStatus = "unverified-source-field" }
quests[11691] = { id = 11691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Ahune", description = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  {name}, you will be the fist of the Earthmother.\n\nTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.\n\nIf fortune is with us, then, perhaps, we can defeat him.\n\nPrepare yourself, {name}.  If Ahune comes to face us, then his fury will be great.", sourceObjective = "Bring the Earthen Ring Magma Totem to the Ice Stone.", progress = "This shard of ice echoes the deep, cracking rumble of invading glaciers.  Its cold turns your thoughts to a lifeless, endless winter.", completion = "The magma totem bursts into three separate flames as it is brought near the ice stone.  The stone shimmers, then is gone...", sourceObjectiveStatus = "unverified-source-field" }
quests[11692] = { id = 11692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check in With Bixie", description = "You're a proven <hero/heroine>. I have another problem!\n\nMy boss, Tinky, went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! Tinky's the only one that can fix it and we really need it working one-hundred percent.\n\nYou think you could find them? Bixie said something about following some old magnataur to a place called The Dens of Dying.\n\nI'm guessing that's where you'll find them.\n\nYou can catch a ride out there by talking with Kara Thricestar at the runway.", sourceObjective = "Mordle Cogspinner has asked you to find Bixie Wrenchshanker to the south of The Dens of Dying.", completion = "What do you need, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11693] = { id = 11693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Great... Plagued Magnataur!", description = "Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die.\n\nOf course, we had no idea that they were going to get plagued when they went in there. We can't have plagued things just roaming about; it's not healthy.\n\nSay, why don't you put down a number of those things while I figure out what our next step should be?", sourceObjective = "Kill 10 Plagued Magnataur and then return to Bixie Wrenchshanker to the south of The Dens of Dying.", progress = "Doesn't look like enough of the plagued magnataur have been put down yet, {class}.\n\nThink you could take care of a few more before coming back?", completion = "Nice work, but I'd grab a shower the next chance you get.\n\nNow, let's really deal with the problem out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11694] = { id = 11694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Something Going On In Those Caves", description = "So, while you were out taking care of those plagued beasts, I took a peek inside the caves up there.\n\nThere are cultists in there plaguing them!\n\nThey have some sort of noxious concoction brewing in a cauldron. I have a powder that I normally use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize their brew!\n\nTake it up to one of those caves and see if it works.", sourceObjective = "Bixie Wrenchshanker, skulking just to the south of The Dens of Dying, has asked you to use Bixie's Inhibiting Powder at a Den of Dying Plague Cauldron to neutralize it.", completion = "I knew you had it in you. Now there's something else that I need to ask you to take care of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11695] = { id = 11695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horn of Elemental Fury", description = "I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we'll need help and a bit of luck.\n\nLegend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if the legend is true, but it's our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.", sourceObjective = "Reclaim the Lower Horn Half and Upper Horn Half from Chieftain Burblegoggle and Chieftain Gurgleboggle and bring them to Wind Tamer Barah at Taunka'le Village.", progress = "Were you able to find the horn? Was the legend true?", completion = "<Barah accepts the pieces of the horn from you and begins trying to fit them together.>\n\nStormhoof would be proud of you, {name}. Perhaps when we've dealt with the Scourge, I will take the horn with me on a pilgrimage to Stormhoof's tomb.", sourceObjectiveStatus = "unverified-source-field" }
quests[11696] = { id = 11696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune is Here!", description = "{name}, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, {name}.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.", sourceObjective = "Find Luma Skymother in the Slave Pens.", completion = "The cold of Ahune spreads through these caverns, {name}; a seed of the frigid death that awaits us if he gains his full strength.  I thank the Earthmother for sending you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11697] = { id = 11697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rats, Tinky Went into the Necropolis!", description = "I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west.\n\nI'm 100% certain that those cultists came from inside that thing, which means I'm now 100% certain that Tinky's in trouble!\n\nShe's the airstrip's number one engineer. Without her we're doomed!\n\nI'd find her myself, but one of those things got in a swipe on my leg before I could vanish again. {name}, if anyone can get her out, it's you!", sourceObjective = "Find Tinky Wickwhistle inside Talramas.", completion = "Hey there! Who are you?\n\nBixie sent you? Excellent, let's get me out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[11698] = { id = 11698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might As Well Wipe Out the Scourge", description = "If the cultists up in those caves survived the crash, then that fallen necropolis to the west can only be assumed to still be filled with Scourge. There're probably lots of them out in front of it in the pools, too!\n\nWhile you're at Talramas, {class}, do you think you could dispatch all of the Lich King's flunkies that you find there?", sourceObjective = "Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Bixie Wrenchshanker just to the south of The Dens of the Dying.", completion = "Thanks, {name}.\n\nThe Lich King and his Scourge are really scary, but we can't stop until they are all lying still in new graves!", sourceObjectiveStatus = "unverified-source-field" }
quests[11699] = { id = 11699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Stuck in this Damned Cage... But Not For Long!", description = "The cultists magicked me into this cage and there's no door to it. Little did they know that I'm the chief transmatter engineer for the airstrip!\n\nWith your help, and a little elbow-grease, I won't be in here for long.\n\nI'm going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top.\n\nWith all of that stuff, I should be able to make a port device to get back to Fizzcrank's and escape the gnome way!", sourceObjective = "Collect an Engine-Core Crystal, a Magical Gyroscope, and a Piloting Scourgestone. Deliver them to Tinky Wickwhistle at Talramas.", progress = "You got all of that stuff?", completion = "Outstanding! Now just a little modification here, and a tweak there....", sourceObjectiveStatus = "unverified-source-field" }
quests[11700] = { id = 11700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Bixie Know", description = "My evil twin's out there somewhere now.\n\nI'm pretty sure that she's not back at the airstrip. In fact, wherever she ended up, it's colder there than here. But I could only 'feel' her for a moment.\n\nOh well, I'll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I'll meet her back there?\n\nThanks, {name}!", sourceObjective = "Speak with Bixie Wrenchshanker just south of The Dens of Dying.", completion = "Tinky's got an evil twin?!\n\nWell, if she says she's okay, and that she'll be able to get herself back to the airstrip soon, that's good enough for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[11701] = { id = 11701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Airstrip", description = "Okay, I think I'm going to start making my way back to the airstrip, too. Of course, I'm moving a little slower with this leg injury.\n\nSay, do you think you could get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that there'll be a reward in it for you.\n\nThanks, {name}!", sourceObjective = "Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip in Borean Tundra.", completion = "That's quite a tale, {name}. With all of the problems out here, it's a wonder that the airstrip hasn't been wiped out already.\n\nBut, thanks to you, there's one less adversary to worry about.\n\nI put aside some special things for just such an occasion as this. Why don't you take your pick?", sourceObjectiveStatus = "unverified-source-field" }
quests[11702] = { id = 11702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Mrgl-Mrgl", description = "Dis is gonna sound weird, {class}, but dere be a murloc askin' for our help!\n\nHe goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and his people been run outa dere village and wantin' you to come save dem.\n\nYou find him by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin Retreat.", sourceObjective = "Speak with King Mrgl-Mrgl at Winterfin Retreat.", completion = "Finally, help! And by the looks of you, Horde.\n\nThat's alright... your people are very skilled in the art of combat. We're going to need a lot of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11703] = { id = 11703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Getry", description = "The Scourge agent that's overseeing the abduction and transformation of Horde soldiers into undead monsters is using the northwest farm as a spawning glade. Shadowstalker Getry has been staking out that monster for the past week and has gathered some vital information that might allow us to end this menace.\n\nGet to Getry and see if you can help him put a stop to this Scourge assembly line. You'll find Getry at the abandoned tower on the northwest border of these farms.", sourceObjective = "Find Shadowstalker Getry at Warsong Farms.", completion = "<Getry looks you over.>\n\nThis is all Ickoris could send?", sourceObjectiveStatus = "unverified-source-field" }
quests[11704] = { id = 11704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Mrgl-Mrgl", description = "This is the weirdest thing, {class}, but there's a murloc asking for our help!\n\nHe goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It would seem that he and his people have been run out of their village and they want someone to come save them.\n\nThat someone is you!\n\nYou'll find Winterfin Retreat, and the king, by heading west down the road until you come to the cliffs. Head down to the water line near the Blistering Pool.", sourceObjective = "Speak with King Mrgl-Mrgl at Winterfin Retreat.", completion = "Finally, help! And by the looks of you, Alliance.\n\nThat's good... your people are very skilled in the art of combat. We're going to need a lot of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11705] = { id = 11705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foolish Endeavors", description = "This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions?\n\n<Getry sighs.>\n\nIf Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh?\n\nWhen you're ready we will descend and face Varidus.\n\nIf we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.", sourceObjective = "Help Getry defeat Varidus the Flenser at Warsong Farms.\n\nReport to Garrosh Hellscream should you succeed.", completion = "And you returned victorious, just as I thought! I told Saurfang you'd be fine.\n\n<Hellscream grunts knowingly.>\n\nPerhaps this will show that old dog that he doesn't have all the answers, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[11706] = { id = 11706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Collapse", description = "I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn's call when you stand near the southernmost sinkhole in the Geyser Fields.\n\nThe quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn't be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn't break the back of their assault, the defeat of their leader surely will.", sourceObjective = "Wind Tamer Barah at Taunka'le Village wants you to collapse the Nerubian sinkholes using the Horn of Elemental Fury and defeat Lord Kryxix.", progress = "Have you unleashed Alluvius and destroyed the Nerubian assault?", completion = "Your efforts against the Nerubians have given us a reprieve from the overwhelming Scourge assault. Thanks to your accomplishments, we can strike at the the Scourge fortress to the northeast without fear of attack from the west.\n\nAs for the horn, I will safeguard it until next we need its power. Stormhoof gave his life to secure the horn and we cannot suffer its loss again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11707] = { id = 11707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distress Call", description = "Oh good, you're {name}, right?\n\nWe need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station!\n\nIt's madness I tell you, madness!\n\nYou've got to head up there and talk to old man Fullthrottle a.s.a.p.!", sourceObjective = "Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip.", completion = "I see that Skyhopper finally got around to sending help. And none too soon I might add!\n\nWelcome, brother, we need your help badly!", sourceObjectiveStatus = "unverified-source-field" }
quests[11708] = { id = 11708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mechagnomes", description = "Now that you're here, it's time for me to tell you the full story of what's going on.\n\nAfter you've heard my tale, go outside and find my second-in-command, Jinky Wingnut. She'll handle everything from here on out.", sourceObjective = "Listen to Fizzcrank Fullthrottle's tale and then find Jinky Wingnut at Fizzcrank Airstrip.", progress = "Hello there.", completion = "The old man sent you to me, huh? He tell you everything that's going on out here?\n\nGood... let's take care of business then!", sourceObjectiveStatus = "unverified-source-field" }
quests[11709] = { id = 11709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nork Bloodfrenzy's Charge", description = "While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange.\n\nYou are dismissed, {name}.", sourceObjective = "Speak to Warden Nork Bloodfrenzy at Warsong Hold in Borean Tundra.", completion = "<Nork scoffs.>\n\nPrisoners? These aren't prisoners. They're cowardly dogs! Just look at 'em. Did you know that without exception, every single one of these yellow-bellied \"soldiers\" came to our gates and surrendered their arms and armor?\n\nFrom what we've been able to gather, these men and women are discharged and sent back to their homes if captured by us.\n\n<Nork spits.>\n\nPathetic...", sourceObjectiveStatus = "unverified-source-field" }
quests[11710] = { id = 11710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's the Matter with the Transmatter?", description = "There're spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned.\n\nI'd hate to see another accident....", sourceObjective = "Collect 15 Fizzcrank Spare Parts and deliver them to Mordle Cogspinner at Fizzcrank Airstrip.", progress = "It's going to take a lot of spare parts to keep this thing running.\n\nPlease tell me that you've returned with everything we need.", completion = "That's great, {class}! These parts look like they're in serviceable condition.\n\nNow if I could only figure out how to fix this blasted thing....", sourceObjectiveStatus = "unverified-source-field" }
quests[11711] = { id = 11711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coward Delivery... Under 30 Minutes or it's Free", description = "We're seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy.\n\n<Nork snorts as he laughs.>\n\nI want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands.\n\nReport to Scout Tungok on the east road once the delivery has been made.", sourceObjective = "Take the Alliance Deserter to the crossroads east of Warsong Hold and fire your Warsong Flare Gun to signal the Alliance.\n\nReport to Scout Tungok once you have successfully delivered the Alliance Deserter to their destination.", progress = "<Tungok grunts.>\n\nDid you take care of the deserter?", completion = "Good job, {name}. That's one less filthy, useless, Alliance scum-bag that we'll have to provide for...\n\nIf you're lookin' for more work, the tauren and blood elf nearby need some help.\n\n'Course we've got our own set of problems to deal with out here as well...", sourceObjectiveStatus = "unverified-source-field" }
quests[11712] = { id = 11712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Cursive", description = "If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the \"Curse of the Flesh\", and now they're robots!\n\nWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.\n\nWe're hoping that this stuff will cure them and allow us to lock onto them to port 'em out of there.\n\nWhaddya say, {name}?", sourceObjective = "Jinky Wingnut at Fizzcrank Airstrip has asked you to use the Re-Cursive Transmatter Injection on 6 Fizzcrank Mechagnomes.", completion = "You did it... it worked!\n\nI can't believe you were able to save so many. We're fortunate to have you around here!", sourceObjectiveStatus = "unverified-source-field" }
quests[11713] = { id = 11713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Sinkholes", description = "Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford to wait any longer for their information, so I'm going to need someone to check out the sinkholes on foot.\n\nI understand the dangers involved, and I'll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.", progress = "Have you marked the locations of the sinkholes?", completion = "<Abner accepts the map from you, then examines it closely.>\n\nGreat! This is all the information we need to begin the operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[11714] = { id = 11714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermin Extermination", description = "Perhaps you'd be interested in helping me clean up these fields? They're littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, they're all over the damned place. The stink alone is making my life hell!\n\nTake care of the vermin for me and I'll make it worth your while, {name}.", sourceObjective = "Scout Tungok at the Bloodspore Plains in the Borean Tundra wants you to kill 8 Bloodspore Harvesters, 5 Bloodspore Firestarters and 2 Bloodspore Roasters.", progress = "This job stinks...", completion = "A job well done, {name}! Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11715] = { id = 11715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Project", description = "I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we'll have to collect the fuel for the device some other way.\n\nOut in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine.\n\nSimply deploy the collector near the rig, and it will pump and store the oil in its tank.", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to collect 8 Barrels of Oil using the Portable Oil Collector.", progress = "Do you have that fuel?", completion = "<Abner sets about draining the fuel tank of the collector.>\n\nDistilling this by hand is going to be messy, but I'll have it taken care of soon. In the meantime, we'll need one more material to complete the machine.", sourceObjectiveStatus = "unverified-source-field" }
quests[11716] = { id = 11716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wondrous Bloodspore", description = "We are witnessing something amazing here, {race}. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz.\n\nI have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You'll find them near the larger plants surrounding us.\n\nBe wary of their guardians! The kobolds won't give them up easily!", sourceObjective = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels.", progress = "The tests must continue!", completion = "Lovely! Just lovely!\n\n<Laurith applies a sprinkling of pollen to one of the bloodspore carpels and then utters an incantation.>\n\nHrmph... I don't understand. Unless... Why of course!", sourceObjectiveStatus = "unverified-source-field" }
quests[11717] = { id = 11717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen from the Source", description = "It's obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth's internal system that acts as a catalyst for this pollen to work. It's all starting to make sense now, {name}. That's why the kobolds don't kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!\n\nWell we'll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?", sourceObjective = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen.", progress = "The pollen is the key!", completion = "A-ha!\n\n<Laurith sprinkles the moth pollen onto the bloodspore carpels.>\n\nLook at that!", sourceObjectiveStatus = "unverified-source-field" }
quests[11718] = { id = 11718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bot in Mammoth's Clothing", description = "I've reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend's biting cold.\n\nI've devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we'll be able to unleash it on the Nerubians!", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides.", progress = "Bring those hides as quickly as possible! I won't be able to finish the machine without them!", completion = "<Abner inspects the hides, coughing at all the dust rising from them.>\n\nDon't these animals even try to keep clean? Some of these are absolutely filthy. Well, I guess I'd better get started cleaning them. It's not like anyone's got spare time around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11719] = { id = 11719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Test Subject", description = "<Laurith looks you over as if to size you up.>\n\nSo we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway?\n\nDon't you worry, {name}! Just take this sample and rub it all over your face.", sourceObjective = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.", progress = "Don't be afraid.", completion = "Primal Mighthorn will be delighted! This is better than even I expected!\n\nPerhaps it's time that I told you the truth.", sourceObjectiveStatus = "unverified-source-field" }
quests[11720] = { id = 11720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Invasion of Gammoth", description = "Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left...\n\nWe aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail...\n\nSpeak to Primal Mighthorn now.", sourceObjective = "Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", completion = "The bloodspore that you collected might just be enough to give us an edge against the magnataurs of Gammoth - with your help, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[11721] = { id = 11721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammothra the Tormentor", description = "Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.\n\nTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.", sourceObjective = "Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", progress = "The powder can be used to weaken all magnataur. It is why the rat men of the area guard it so closely.", completion = "A job well done, {name}! Would you honor Laurith and I by taking the head of the beast and presenting it to Hellscream? He will be extremely pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[11722] = { id = 11722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophies of Gammoth", description = "We cannot take all of the credit for this Horde victory, {name}. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.\n\nHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.", sourceObjective = "Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.", progress = "Back so soon?", completion = "<Hellscream picks up the head of Gammothra with one arm and spits in its face.>\n\nThey will learn, {name}... They will all learn. The Horde is not to be trifled with...", sourceObjectiveStatus = "unverified-source-field" }
quests[11723] = { id = 11723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deploy the Shake-n-Quake!", description = "Behold, the machine that will save us from the Nerubian threat!\n\n<Abner beams with pride as he presents the finished bot.>\n\nTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.\n\nDon't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.", sourceObjective = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.", progress = "Well, have you deployed the Shake-n-Quake 5000 yet?", completion = "<Abner listens eagerly as you report your success and the success of the Shake-n-Quake 5000.>\n\nFizzcrank will be delighted to hear the news! And who knows, perhaps we'll make a mechanic of you yet!", sourceObjectiveStatus = "unverified-source-field" }
quests[11724] = { id = 11724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massive Moth Omelet?", description = "This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!\n\nCollect the egg and take it to the expectant Bloodmage.", sourceObjective = "Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra.", progress = "Greetings!", completion = "Alkor is no more, eh? A pity... As for the egg, we have no real use for it anymore. We've got much bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
quests[11725] = { id = 11725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Pilot Tailspin", description = "I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.\n\nNo, it's just that it's my responsibility to lead a mission of such import.\n\nI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.\n\nThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.\n\nFind Tailspin, {name}.", sourceObjective = "Locate Iggy \"Tailspin\" Cogtoggle in the Geyser Fields.", completion = "Thank goodness. It was terrible.\n\nThere was a bright flash on the ground, and then, the next thing I know, the squadron's going down! I'm hurt pretty badly, so I haven't had a chance to comb the site for other survivors, but something tells me I don't think there will be many.\n\n<Iggy grimaces in pain.>\n\nWill you help me complete my mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[11726] = { id = 11726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Bit of Spice", description = "The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process.\n\nI have a plan to recover that microfilm, but I need your help to make it work.\n\nTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.", sourceObjective = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches.", progress = "Do you have those spice pouches?", completion = "<Iggy holds his nose as he empties the spice pouches and addresses you in a nasal voice.>\n\nNow that we have what we need, I'll combine it with my emergency rations to create a bait for the wolves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11727] = { id = 11727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time for Heroes", description = "It's good to have you among us, {name}.  We've all heard of your past deeds.\n\nAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.\n\nI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.\n\nReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.", sourceObjective = "Report to Sergeant Hammerhill at Valiance Keep.", completion = "By Magni's beard!  Looks like the heavy artillery's arriving.", sourceObjectiveStatus = "unverified-source-field" }
quests[11728] = { id = 11728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupus Pupus", description = "Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait.\n\nSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.\n\nI'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.", sourceObjective = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm.", progress = "Have you recovered the microfilm?", completion = "<Iggy holds his nose as he accepts the microfilm from you.>\n\nYuck, well, we've complied with section 8.2, paragraph B of the emergency protocol here and recovered the film. Nothing in the protocol says I'm responsible for cleaning it, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[11729] = { id = 11729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultrasonic Screwdriver", description = "The unit you just dismantled had this inside of its mechanical innards.\n\nIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?", sourceObjective = "Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Hey!", completion = "My screwdriver... you found my screwdriver! I'd been wondering where that thing got lost.\n\nHmm, you found it inside one of their robots, you say? That gives me an idea....", sourceObjectiveStatus = "unverified-source-field" }
quests[11730] = { id = 11730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master and Servant", description = "The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!\n\nHead back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway.\n\nI'm pretty sure it won't work on the mechagnomes, so don't even bother with them.\n\nOh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!", sourceObjective = "Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip.\n\nMake sure to loot the dead robot before you reprogram it.", progress = "How many robots have you managed to reprogram?", completion = "Woo hoo! And you brought back the screwdriver intact, too!\n\nReprogramming those robots is going to turn out to be a huge advantage in our favor in the fight against Gearmaster Mechazod. I think you've earned a little something for that.", sourceObjectiveStatus = "unverified-source-field" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lession.", sourceObjective = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", sourceObjectiveStatus = "unverified-source-field" }
quests[11732] = { id = 11732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Arathi Highlands bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11733] = { id = 11733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traversing the Rift", description = "I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you.\n\nThe time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept.\n\nBefore hearing the tale, you shall be shown firsthand what we face.\n\nPut your affairs in order, {class}....", sourceObjective = "Surristrasz wants you to travel to Coldarra. Once there, you are to speak with Archmage Berinand.", completion = "Welcome to Coldarra, {class}.\n\nUnder the Transitus Shield we lie hidden just a stone's throw from the Nexus, fortress of the great aspect Malygos and his blue dragonflight.\n\nDo make yourself comfortable.", sourceObjectiveStatus = "unverified-source-field" }
quests[11734] = { id = 11734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Ashenvale bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11735] = { id = 11735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Azuremyst Isle bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11736] = { id = 11736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Blade's Edge Mountains bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11737] = { id = 11737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Blasted Lands bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11738] = { id = 11738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Bloodmyst Isle bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11739] = { id = 11739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Burning Steppes bonfire!", sourceObjectiveStatus = "unverified-source-field" }
