quests[11787] = { id = 11787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Zangarmarsh bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11788] = { id = 11788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lefty Loosey, Righty Tighty", description = "Okay, I think we're ready for the penultimate assault... before you can bring down Mechazod, you're going to have to dismantle his lieutenants first!\n\nYou'll find Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point and South Point stations, respectively.\n\nTo get them to show up, just turn the valves at the stations to mess up whatever they're trying to do out there. You can't miss the places, they all have spinning lights.", sourceObjective = "Dismantle Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Jinky Wingnut at Fizzcrank Airstrip.", progress = "Are Gearmaster Mechazod's lieutenants dealt with?", completion = "Wow, you survived!\n\nI guess all that's left to do now is to deal with Gearmaster Mechazod.", sourceObjectiveStatus = "unverified-source-field" }
quests[11789] = { id = 11789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soldier in Need", description = "You there!  Please, I need your help.  This soldier will succumb to the cryptfiends' venom unless we act immediately.\n\nI've managed to slow down the poison, but without a suitable supply of antidote I cannot counteract it.\n\nI was promised a new shipment of anti-venom in the Stormbreaker's most recent trip from the south.  Go inside its hold and search for a chest of first aid supplies.\n\nHurry, {class}!  We can't afford to lose any more men unnecessarily.", sourceObjective = "Medic Hawthorn, outside of Valiance Keep, wants you to go inside the Stormbreaker's hold and retrieve Hawthorn's Anti-Venom from a crate of First Aid Supplies.", progress = "The anti-venom... do you have it?", completion = "I thank you, {name}.  This man's recovery will be slow, but we won't lose him.\n\nWhat do you say?  You found cultists inside the Stormbreaker?  You'd best notify someone... and bring some evidence.", sourceObjectiveStatus = "unverified-source-field" }
quests[11790] = { id = 11790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", sourceObjective = "Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep.", completion = "Cultists?  Below deck?  I ought to have my whole crew flogged!\n\nListen... why don't we have Admiral Cantlebree take care of this... situation?", sourceObjectiveStatus = "unverified-source-field" }
